insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('df000000-0000-0000-0000-000000000001', 'mrcp2', 'e60794e6-0c28-479e-a555-a842413a0c7c',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('df000000-0000-0000-0000-000000000001', 'A', 'Mycophenolate mofetil combined with high-dose corticosteroids', true, 'Correct. For class IV lupus nephritis, mycophenolate mofetil (MMF) is equivalent in efficacy to cyclophosphamide for induction and is preferred in women of childbearing age who wish to preserve fertility, since cyclophosphamide carries a significant risk of gonadotoxicity and premature ovarian failure. MMF plus high-dose glucocorticoids (with a rapid steroid taper) is now a standard first-line induction regimen per KDIGO/EULAR guidance.', 1),
('df000000-0000-0000-0000-000000000001', 'B', 'Intravenous cyclophosphamide (Euro-Lupus regimen) combined with high-dose corticosteroids', false, $x$Ruled out as first choice here because although cyclophosphamide is an effective and guideline-supported induction option, it carries a dose-dependent risk of gonadotoxicity; given this patient's strong desire for future fertility, MMF is preferred when disease severity allows either agent to be used.$x$, 2),
('df000000-0000-0000-0000-000000000001', 'C', 'Doubling the hydroxychloroquine dose and monitoring response', false, 'Ruled out because hydroxychloroquine alone is inadequate for proliferative (class IV) lupus nephritis with active nephritic sediment and rising creatinine; this requires potent induction immunosuppression, not background therapy alone.', 3),
('df000000-0000-0000-0000-000000000001', 'D', 'Belimumab monotherapy without additional induction agents', false, 'Ruled out because belimumab is licensed as an add-on to standard background therapy (e.g. with MMF or cyclophosphamide), not as monotherapy for active proliferative nephritis; it has no proven role replacing induction immunosuppression in this setting.', 4),
('df000000-0000-0000-0000-000000000001', 'E', 'Rituximab monotherapy without concomitant corticosteroids', false, 'Ruled out because rituximab is not established first-line induction therapy for lupus nephritis (it failed to meet its primary endpoint in the LUNAR trial as monotherapy) and corticosteroids are a necessary component of induction, not something to omit.', 5),
('df000000-0000-0000-0000-000000000002', 'A', 'Switch to rivaroxaban at a standard treatment dose', false, 'Ruled out because direct oral anticoagulants, including rivaroxaban, have been shown in randomised trials (e.g. TRAPS) to be inferior to warfarin and associated with a higher rate of recurrent arterial thrombotic events in triple-positive APS; DOACs should be avoided in this population.', 1),
('df000000-0000-0000-0000-000000000002', 'B', 'Add low-dose aspirin to the existing warfarin regimen without changing INR target', false, 'Ruled out because dual therapy at the same INR target does not address the demonstrated inadequacy of standard-intensity anticoagulation in this high-risk triple-positive patient; the evidence-based response is to intensify anticoagulation, not add antiplatelet therapy at the same INR range.', 2),
('df000000-0000-0000-0000-000000000002', 'C', 'Continue warfarin but increase the target INR to a high-intensity range of 3.0-4.0', true, 'Correct. In triple-positive antiphospholipid syndrome with recurrent arterial thrombosis despite standard-intensity warfarin (INR 2-3), guidelines recommend increasing to high-intensity anticoagulation (target INR 3.0-4.0) with warfarin rather than switching to a direct oral anticoagulant, given the high thrombotic risk in this antibody profile.', 3),
('df000000-0000-0000-0000-000000000002', 'D', 'Discontinue warfarin and switch to therapeutic-dose low molecular weight heparin long-term', false, 'Ruled out because long-term LMWH is not standard maintenance therapy for APS-related arterial thrombosis outside pregnancy or specific circumstances (e.g. warfarin intolerance); high-intensity warfarin remains the preferred approach for recurrent arterial events in triple-positive APS.', 4),
('df000000-0000-0000-0000-000000000002', 'E', 'No change in management, as recurrent TIA on adequate anticoagulation reflects atherosclerotic rather than APS-related disease', false, 'Ruled out because in a young patient with known triple-positive APS and a prior stroke in the same vascular territory, recurrent thrombotic events on standard-intensity warfarin should be attributed to inadequate anticoagulation intensity for this high-risk antibody profile until proven otherwise, not dismissed as an unrelated process.', 5),
('df000000-0000-0000-0000-000000000003', 'A', 'Start high-dose intravenous methylprednisolone as first-line therapy', false, 'Ruled out because high-dose corticosteroids are a recognised precipitant/risk factor for scleroderma renal crisis and are not the treatment for it; corticosteroid use should generally be minimised or avoided in patients with diffuse systemic sclerosis, particularly early in the disease course, for this reason.', 1),
('df000000-0000-0000-0000-000000000003', 'B', 'Withhold ACE inhibitors given the acute kidney injury and manage blood pressure with a calcium channel blocker alone', false, 'Ruled out because withholding ACE inhibitors due to renal impairment is a critical error in scleroderma renal crisis; ACE inhibitors remain indicated and effective even when creatinine is rising, and delaying their use worsens renal outcomes. Calcium channel blockers are not an adequate substitute.', 2),
('df000000-0000-0000-0000-000000000003', 'C', 'Arrange urgent haemodialysis as the primary intervention before considering antihypertensive therapy', false, 'Ruled out because although some patients with scleroderma renal crisis progress to requiring dialysis, the priority intervention is prompt initiation and up-titration of an ACE inhibitor to control the malignant hypertension driving the renal injury; dialysis is supportive, not the primary disease-modifying treatment.', 3),
('df000000-0000-0000-0000-000000000003', 'D', 'Perform plasma exchange as first-line management for the presumed thrombotic microangiopathy', false, 'Ruled out because although scleroderma renal crisis produces a microangiopathic haemolytic picture, it is driven by renin-angiotensin-mediated vasospasm rather than a primary complement- or ADAMTS13-mediated TMA, and plasma exchange is not the established first-line treatment; ACE inhibition is.', 4),
('df000000-0000-0000-0000-000000000003', 'E', 'Start an ACE inhibitor (e.g. captopril) and titrate to control blood pressure, even in the presence of renal impairment', true, 'Correct. This presentation (new severe hypertension, acute kidney injury, microangiopathic haemolytic anaemia and thrombocytopenia in early diffuse systemic sclerosis, particularly with anti-RNA polymerase III antibodies) is scleroderma renal crisis. ACE inhibitors are the mainstay of treatment and should be started and up-titrated promptly regardless of the degree of renal impairment, as they are the only intervention shown to improve renal and overall survival; withholding them due to rising creatinine is a recognised and avoidable cause of poor outcome.', 5),
('df000000-0000-0000-0000-000000000004', 'A', 'High-resolution CT chest repeated in 12 months', false, 'Ruled out because the HRCT has already excluded significant interstitial lung disease as the explanation for her symptoms and reduced DLCO; the pattern described points towards a pulmonary vascular rather than parenchymal process, which HRCT will not adequately assess or confirm.', 1),
('df000000-0000-0000-0000-000000000004', 'B', 'Right heart catheterisation', true, 'Correct. A disproportionately reduced DLCO relative to preserved FVC, in the absence of significant ILD, combined with an elevated NT-proBNP and new exertional dyspnoea, is a classic pattern raising suspicion for pulmonary arterial hypertension (PAH) in systemic sclerosis. Right heart catheterisation is the gold-standard confirmatory investigation required before a diagnosis of PAH is made and before starting PAH-specific therapy (e.g. endothelin receptor antagonists, PDE5 inhibitors).', 2),
('df000000-0000-0000-0000-000000000004', 'C', 'Start an endothelin receptor antagonist empirically', false, 'Ruled out because PAH-specific therapy should not be started without haemodynamic confirmation of pulmonary arterial hypertension by right heart catheterisation; empirical treatment based on echocardiographic/biomarker suspicion alone risks inappropriate treatment and delays accurate diagnosis and risk stratification.', 3),
('df000000-0000-0000-0000-000000000004', 'D', 'Six-minute walk test alone to quantify functional limitation', false, 'Ruled out because while the six-minute walk test is useful for monitoring and prognostication once PAH is diagnosed, it is not diagnostic and would not confirm or exclude pulmonary hypertension; right heart catheterisation is required for definitive diagnosis.', 4),
('df000000-0000-0000-0000-000000000004', 'E', 'Reassure and review in 12 months as part of routine annual screening', false, 'Ruled out because this patient has new symptoms (progressive exertional dyspnoea), a disproportionately reduced DLCO, and elevated NT-proBNP — all red flags for evolving PAH — which warrant prompt further investigation rather than routine annual re-screening.', 5),
('df000000-0000-0000-0000-000000000005', 'A', 'High-dose corticosteroid monotherapy, escalating only if no improvement after 4-6 weeks', false, 'Ruled out because a stepwise, delayed-escalation approach is associated with worse outcomes in anti-MDA5 rapidly progressive ILD, which can be fatal within weeks; the evidence supports early combination immunosuppression rather than corticosteroid monotherapy with delayed escalation.', 1),
('df000000-0000-0000-0000-000000000005', 'B', 'Physiotherapy and supportive care alone, as creatine kinase is only mildly elevated indicating mild disease', false, 'Ruled out because muscle enzyme levels correlate poorly with disease severity in anti-MDA5 dermatomyositis; this antibody subtype causes a hypomyopathic phenotype where skin and rapidly progressive lung disease dominate the clinical picture and drive mortality, irrespective of CK level.', 2),
('df000000-0000-0000-0000-000000000005', 'C', 'Hydroxychloroquine alone for the cutaneous manifestations', false, 'Ruled out because hydroxychloroquine addresses only the cutaneous component and provides no meaningful benefit for rapidly progressive ILD, which is the life-threatening feature requiring urgent systemic immunosuppression.', 3),
('df000000-0000-0000-0000-000000000005', 'D', 'Early aggressive combination immunosuppression (e.g. high-dose corticosteroids with a calcineurin inhibitor and either intravenous cyclophosphamide or rituximab)', true, 'Correct. Anti-MDA5-positive dermatomyositis, especially with a hypomyopathic phenotype, is strongly associated with rapidly progressive interstitial lung disease carrying very high short-term mortality. Outcomes are improved by early initiation of aggressive combination immunosuppression (triple therapy) rather than sequential escalation, given the rapid disease trajectory.', 4),
('df000000-0000-0000-0000-000000000005', 'E', 'Delay immunosuppression until lung biopsy confirms the pattern of interstitial lung disease', false, 'Ruled out because in rapidly progressive ILD associated with anti-MDA5 antibodies, treatment should not be delayed pending biopsy; the clinical, serological and radiological picture is sufficient to justify urgent treatment given how quickly this condition can progress to respiratory failure and death.', 5),
('df000000-0000-0000-0000-000000000006', 'A', $x$Reassurance that parotid enlargement is an expected feature of Sjogren's syndrome requiring no further investigation$x$, false, $x$Ruled out because although parotid enlargement can occur in Sjogren's syndrome itself, the combination of persistence, monoclonal gammopathy, cryoglobulinaemia and hypocomplementaemia constitutes recognised 'red flag' features for lymphoma that mandate further investigation rather than reassurance.$x$, 1),
('df000000-0000-0000-0000-000000000006', 'B', $x$Start rituximab empirically for presumed refractory Sjogren's-related sialadenitis$x$, false, $x$Ruled out because treatment should not be started empirically without first establishing a tissue diagnosis; if lymphoma is present, management differs substantially from that of glandular Sjogren's disease activity, so biopsy must precede treatment decisions.$x$, 2),
('df000000-0000-0000-0000-000000000006', 'C', 'Parotid gland biopsy to exclude MALT lymphoma', true, $x$Correct. Persistent unilateral parotid swelling in primary Sjogren's syndrome, especially with a monoclonal paraprotein, cryoglobulinaemia, and low C4, are recognised risk factors for the development of MALT (mucosa-associated lymphoid tissue) lymphoma, which occurs at substantially increased frequency in Sjogren's syndrome. Biopsy is required to exclude lymphomatous transformation rather than attributing the findings to Sjogren's disease activity alone.$x$, 3),
('df000000-0000-0000-0000-000000000006', 'D', 'Increase hydroxychloroquine dose and review in 6 months', false, 'Ruled out because hydroxychloroquine has no established role in resolving persistent parotid enlargement and does not address the need to exclude lymphoma when high-risk features (paraprotein, cryoglobulins, low C4) are present; delaying investigation risks missing a treatable malignancy.', 4),
('df000000-0000-0000-0000-000000000006', 'E', 'Arrange salivary gland ultrasound only, with no tissue sampling', false, 'Ruled out because although ultrasound can support imaging characterisation, definitive exclusion of lymphoma in a persistently enlarged gland with these high-risk serological features requires histological sampling (biopsy), not imaging alone.', 5),
('df000000-0000-0000-0000-000000000007', 'A', 'Stop hydroxychloroquine and consider an alternative disease-modifying agent', true, 'Correct. Once objective evidence of hydroxychloroquine retinopathy is identified on screening (even if asymptomatic), the drug should be discontinued to prevent further progression, as retinal damage can continue to progress and is not reversible; an alternative agent should be considered for ongoing disease control.', 1),
('df000000-0000-0000-0000-000000000007', 'B', 'Continue the same dose since she is visually asymptomatic', false, 'Ruled out because retinal toxicity can be detected on OCT/visual field testing before symptoms develop, which is precisely the rationale for screening; waiting for symptoms before acting risks progression to irreversible visual loss.', 2),
('df000000-0000-0000-0000-000000000007', 'C', 'Reduce the dose to below 5 mg/kg/day and continue with more frequent monitoring', false, 'Ruled out because once retinal toxicity has already been identified, dose reduction alone is not considered adequate; established guidance (Royal College of Ophthalmologists/American Academy of Ophthalmology) recommends stopping the drug once retinopathy is confirmed, since continued exposure risks further, irreversible damage.', 3),
('df000000-0000-0000-0000-000000000007', 'D', 'Switch to chloroquine, which has a lower risk of retinal toxicity', false, 'Ruled out because chloroquine actually carries a higher risk of retinal toxicity than hydroxychloroquine, not a lower one, and would be an inappropriate substitute in a patient who has already developed retinopathy.', 4),
('df000000-0000-0000-0000-000000000007', 'E', 'Repeat OCT in 12 months as part of routine screening with no change to therapy', false, 'Ruled out because this describes the standard *screening* schedule for patients without evidence of toxicity; once toxicity has been identified, the appropriate action is to stop the drug promptly, not to defer reassessment for another year on unchanged therapy.', 5),
('df000000-0000-0000-0000-000000000008', 'A', 'Scleroderma renal crisis, requiring urgent ACE inhibitor prophylaxis', false, 'Ruled out because scleroderma renal crisis is specifically associated with diffuse cutaneous systemic sclerosis (particularly anti-RNA polymerase III positivity), not with anti-U1-RNP-positive mixed connective tissue disease; prophylactic ACE inhibition is not indicated here.', 1),
('df000000-0000-0000-0000-000000000008', 'B', 'Pulmonary arterial hypertension, with periodic echocardiographic and symptom-based screening', true, $x$Correct. Mixed connective tissue disease (anti-U1-RNP positive, with the described overlap features of Raynaud's, puffy hands, myositis and arthritis) carries a recognised risk of pulmonary arterial hypertension, which can develop insidiously and is a major cause of mortality in MCTD; regular screening (similar in principle to systemic sclerosis) is recommended even in asymptomatic patients.$x$, 2),
('df000000-0000-0000-0000-000000000008', 'C', 'Coronary artery disease requiring routine annual angiography', false, 'Ruled out because although connective tissue diseases carry increased cardiovascular risk, routine angiography is not indicated as a surveillance tool, and this is not the specific, characteristic organ complication associated with this antibody profile.', 3),
('df000000-0000-0000-0000-000000000008', 'D', 'Anti-glomerular basement membrane disease requiring renal biopsy surveillance', false, 'Ruled out because anti-GBM disease is not a recognised association of mixed connective tissue disease or anti-U1-RNP positivity; this is not an appropriate screening target here.', 4),
('df000000-0000-0000-0000-000000000008', 'E', 'Avascular necrosis of the femoral head requiring routine hip MRI', false, 'Ruled out because avascular necrosis is typically related to corticosteroid exposure or antiphospholipid syndrome rather than being a defining feature specifically screened for in MCTD based on antibody profile.', 5),
('df000000-0000-0000-0000-000000000009', 'A', 'Corticosteroids alone, with no additional immunosuppression, since muscle weakness is the dominant feature', false, 'Ruled out because in antisynthetase syndrome the interstitial lung disease often determines prognosis and can progress despite adequate control of myositis; corticosteroid monotherapy is generally insufficient, and a steroid-sparing agent addressing both muscle and lung disease is required.', 1),
('df000000-0000-0000-0000-000000000009', 'B', 'Physiotherapy alone with deferral of immunosuppression until muscle weakness becomes disabling', false, 'Ruled out because this presentation already has evidence of active myositis and early ILD, both of which warrant prompt immunosuppressive treatment rather than delay; deferring treatment risks progression of potentially irreversible lung fibrosis.', 2),
('df000000-0000-0000-0000-000000000009', 'C', 'Methotrexate monotherapy, avoiding corticosteroids due to steroid myopathy risk', false, 'Ruled out because corticosteroids remain a core component of initial therapy for active myositis; concern about steroid myopathy does not outweigh the need to control significant inflammatory disease, and methotrexate alone is not an adequate substitute given lung involvement.', 3),
('df000000-0000-0000-0000-000000000009', 'D', 'Antifibrotic therapy (e.g. nintedanib) as first-line treatment without immunosuppression', false, 'Ruled out because the ILD here is inflammatory/autoimmune in nature (associated with active antisynthetase syndrome) and the priority is immunosuppression; antifibrotic agents have a more established role in progressive fibrotic ILD once inflammatory activity has been addressed, not as first-line monotherapy in newly active connective tissue disease-associated ILD.', 4),
('df000000-0000-0000-0000-000000000009', 'E', 'Combined immunosuppression with corticosteroids and a steroid-sparing agent (e.g. azathioprine, mycophenolate or rituximab), with ongoing surveillance of lung disease', true, $x$Correct. This presentation (myositis, mechanic's hands, inflammatory arthritis and anti-Jo-1-positive interstitial lung disease) is classic antisynthetase syndrome. Because ILD is often the major driver of long-term morbidity and can progress independent of muscle disease activity, management requires combined immunosuppression targeting both myositis and lung disease, with regular pulmonary function and imaging surveillance, rather than treating the muscle disease in isolation.$x$, 5),
('df000000-0000-0000-0000-000000000010', 'A', 'Continue mycophenolate mofetil throughout pregnancy since her disease is currently quiescent', false, 'Ruled out because mycophenolate mofetil is teratogenic and contraindicated in pregnancy regardless of current disease quiescence; it must be stopped and substituted with a pregnancy-compatible agent well before conception.', 1),
('df000000-0000-0000-0000-000000000010', 'B', 'Stop hydroxychloroquine before conception due to concerns about fetal toxicity', false, 'Ruled out because hydroxychloroquine is safe in pregnancy and its continuation is specifically recommended, as stopping it increases the risk of maternal flare without any proven fetal benefit from discontinuation.', 2),
('df000000-0000-0000-0000-000000000010', 'C', 'Switch mycophenolate mofetil to methotrexate to maintain immunosuppression during pregnancy', false, 'Ruled out because methotrexate is also strongly teratogenic and abortifacient, and is absolutely contraindicated in pregnancy; it would not be an appropriate substitute.', 3),
('df000000-0000-0000-0000-000000000010', 'D', 'Switch mycophenolate mofetil to azathioprine at least 3 months before attempting conception, and continue hydroxychloroquine', true, 'Correct. Mycophenolate mofetil is teratogenic (associated with cleft lip/palate and other malformations) and must be discontinued before conception; azathioprine is considered relatively safe in pregnancy and is the preferred substitute to maintain disease control during the transition. Hydroxychloroquine should be continued throughout pregnancy, as it reduces flare risk and is safe for both mother and fetus.', 4),
('df000000-0000-0000-0000-000000000010', 'E', 'Stop all immunosuppression entirely at least 6 months before conception to minimise any drug exposure', false, 'Ruled out because abrupt cessation of all immunosuppression risks a disease flare in a patient with a history of lupus nephritis; the correct approach is to transition to a pregnancy-compatible steroid-sparing agent (azathioprine) rather than stopping treatment altogether, while continuing hydroxychloroquine.', 5),
('df000000-0000-0000-0000-000000000011', 'A', 'High-dose oral NSAID (e.g. naproxen 500mg twice daily) as first-line therapy', false, 'Ruled out because NSAIDs are relatively contraindicated in patients with significant CKD (eGFR 24) due to risk of worsening renal function and fluid overload; safer alternatives (corticosteroids or dose-adjusted colchicine) should be used instead.', 1),
('df000000-0000-0000-0000-000000000011', 'B', 'Standard full-dose colchicine (e.g. 500 micrograms four times daily) without renal dose adjustment', false, 'Ruled out because standard colchicine dosing is not appropriate in significant renal impairment; accumulation risks serious toxicity including bone marrow suppression, neuromyopathy and multi-organ failure, so the dose must be substantially reduced or the drug avoided altogether in advanced CKD.', 2),
('df000000-0000-0000-0000-000000000011', 'C', 'Start allopurinol immediately at a treatment dose to abort the acute flare', false, 'Ruled out because urate-lowering therapy does not treat an acute flare and, if anything, can transiently worsen symptoms through urate mobilisation; the acute flare requires anti-inflammatory treatment, with urate-lowering therapy addressed separately (and, per current practice, can be started concurrently with adequate anti-inflammatory cover, but is not itself the acute treatment).', 3),
('df000000-0000-0000-0000-000000000011', 'D', 'A short course of oral corticosteroids (e.g. prednisolone), or renally dose-reduced low-dose colchicine, avoiding NSAIDs', true, 'Correct. In a patient with significant CKD (eGFR 24), NSAIDs should be avoided due to the risk of further nephrotoxicity and fluid retention. A short course of oral corticosteroids is an effective and CKD-safe option for an acute gout flare; if colchicine is used instead, the dose must be substantially reduced and given cautiously given reduced renal clearance and the risk of accumulation and toxicity (myopathy, marrow suppression) in significant renal impairment.', 4),
('df000000-0000-0000-0000-000000000011', 'E', 'Intra-articular hyaluronic acid injection', false, 'Ruled out because hyaluronic acid injection is used for degenerative joint disease (e.g. osteoarthritis), not for treating an acute inflammatory gout flare; it has no established role here.', 5),
('df000000-0000-0000-0000-000000000012', 'A', 'Switch directly to febuxostat at a standard dose without further allopurinol titration', false, 'Ruled out because febuxostat has been associated with an increased risk of cardiovascular death compared with allopurinol in patients with pre-existing cardiovascular disease (CARES trial); in a patient with prior myocardial infarction, this should not be a first-line switch before allopurinol has been adequately optimised.', 1),
('df000000-0000-0000-0000-000000000012', 'B', 'Stop urate-lowering therapy altogether given persistently elevated urate despite treatment, and manage flares symptomatically only', false, 'Ruled out because persistently elevated urate on suboptimal dosing is a reason to optimise treatment (dose escalation or considering alternative agents), not to abandon urate-lowering therapy; uncontrolled hyperuricaemia risks progressive tophaceous disease and joint damage.', 2),
('df000000-0000-0000-0000-000000000012', 'C', 'Increase the allopurinol dose further (treat-to-target dose escalation), monitoring renal function and for hypersensitivity', true, $x$Correct. Allopurinol is frequently underdosed at a standard 300mg; treat-to-target strategy involves escalating the dose (with monitoring) until target urate is achieved, and doses above 300mg are safe and effective in patients with normal renal function. Given this patient's ischaemic heart disease, switching to febuxostat should be approached cautiously (per the CARES trial cardiovascular safety signal in patients with established cardiovascular disease), so optimising allopurinol dosing first is preferred over an early switch.$x$, 3),
('df000000-0000-0000-0000-000000000012', 'D', 'Add a thiazide diuretic to help lower urate levels', false, $x$Ruled out because thiazide diuretics raise serum urate levels and would worsen, not improve, this patient's hyperuricaemia; they are a recognised cause of secondary gout, not a treatment.$x$, 4),
('df000000-0000-0000-0000-000000000012', 'E', 'Start pegloticase as first-line escalation before further optimising oral xanthine oxidase inhibitor therapy', false, 'Ruled out because pegloticase is reserved for refractory chronic tophaceous gout that has failed to respond to appropriately dosed oral urate-lowering therapies; allopurinol dose optimisation should be exhausted first.', 5),
('df000000-0000-0000-0000-000000000013', 'A', 'Delay starting allopurinol until the acute flare has completely settled and the patient has been symptom-free for at least 6 weeks', false, 'Ruled out because although this was traditional teaching, current evidence and guidelines support starting urate-lowering therapy during an acute flare (with adequate anti-inflammatory cover), as this does not worsen outcomes and avoids the risk that patients are lost to follow-up before ULT is ever started.', 1),
('df000000-0000-0000-0000-000000000013', 'B', 'Start allopurinol now, alongside anti-inflammatory treatment of the acute flare and prophylactic colchicine cover', true, 'Correct. Current practice supports initiating urate-lowering therapy during an acute flare (rather than waiting for the flare to fully resolve), provided the acute attack is adequately treated with anti-inflammatory therapy and the patient is given prophylactic cover (e.g. low-dose colchicine or NSAID) against flares precipitated by urate mobilisation as treatment begins. Delaying urate-lowering therapy is no longer considered necessary and risks loss to follow-up.', 2),
('df000000-0000-0000-0000-000000000013', 'C', 'Start febuxostat as first-line urate-lowering therapy in preference to allopurinol', false, 'Ruled out because allopurinol remains the first-line xanthine oxidase inhibitor for most patients; febuxostat is generally reserved for those intolerant of or with an inadequate response to allopurinol, particularly given its cardiovascular safety signal in patients with cardiovascular disease.', 3),
('df000000-0000-0000-0000-000000000013', 'D', 'Avoid urate-lowering therapy since this is only the third attack, reserving it for more frequent recurrences', false, 'Ruled out because recurrent attacks (this being the third within under a year) combined with a markedly elevated serum urate are an indication to initiate urate-lowering therapy to prevent further flares and long-term joint damage, not to defer treatment further.', 4),
('df000000-0000-0000-0000-000000000013', 'E', 'Start colchicine prophylaxis alone indefinitely without any urate-lowering therapy', false, 'Ruled out because colchicine prophylaxis reduces flare frequency but does not address the underlying hyperuricaemia driving recurrent attacks and progressive joint/tissue urate deposition; definitive management requires urate-lowering therapy, with colchicine used as short-term cover during initiation.', 5),
('df000000-0000-0000-0000-000000000014', 'A', 'Send synovial fluid for Gram stain and culture, and start empirical antibiotics while awaiting results, without assuming pseudogout fully explains the presentation', true, 'Correct. Fever, marked leucocytosis, and a very high synovial white cell count raise concern for concurrent septic arthritis, which can coexist with crystal arthropathy (CPPD does not protect against, and can even mimic, joint infection). The presence of CPPD crystals on microscopy does not exclude septic arthritis, so fluid must still be sent for Gram stain/culture and empirical antibiotics started pending results, given the potentially serious consequences of missing a septic joint.', 1),
('df000000-0000-0000-0000-000000000014', 'B', 'Treat as pseudogout alone with NSAIDs, since crystals have been identified on microscopy', false, 'Ruled out because identifying crystals on synovial fluid microscopy does not exclude coexisting septic arthritis; the fever, marked leucocytosis and very high synovial cell count in this case are concerning for infection, which must be actively excluded with culture and covered empirically, not assumed away by the crystal finding.', 2),
('df000000-0000-0000-0000-000000000014', 'C', 'Discharge home with oral colchicine and outpatient rheumatology follow-up', false, 'Ruled out because this presentation (fever, marked leucocytosis, very high synovial WCC, inability to weight-bear) requires inpatient assessment and treatment to exclude and empirically cover for septic arthritis, which can be limb- and life-threatening if missed; outpatient management is inappropriate.', 3),
('df000000-0000-0000-0000-000000000014', 'D', 'Administer an intra-articular corticosteroid injection immediately to settle the inflammatory flare', false, 'Ruled out because intra-articular steroid injection is contraindicated until septic arthritis has been reasonably excluded, since injecting a potentially infected joint risks seeding infection and worsening outcomes.', 4),
('df000000-0000-0000-0000-000000000014', 'E', 'Await synovial fluid culture results before starting any antibiotic therapy', false, 'Ruled out because in a clinical picture concerning for septic arthritis, empirical antibiotics should be started promptly after appropriate cultures are taken, not delayed until culture results (which can take 48+ hours) are available, given the risk of joint destruction and sepsis from untreated infection.', 5),
('df000000-0000-0000-0000-000000000015', 'A', 'Proceed directly to allopurinol at a low starting dose without any genetic screening, since dose titration alone mitigates hypersensitivity risk', false, 'Ruled out because dose titration reduces the risk of hyperuricaemia-related flares on initiation but does not mitigate the risk of allopurinol hypersensitivity syndrome, which is an idiosyncratic immune-mediated reaction strongly linked to HLA-B*5801 in this ethnic group; screening is specifically recommended before starting therapy in high-risk populations.', 1),
('df000000-0000-0000-0000-000000000015', 'B', 'Avoid allopurinol altogether in all patients of Han Chinese ethnicity regardless of HLA-B*5801 status', false, 'Ruled out because HLA-B*5801 screening allows identification of the specific at-risk individuals; a positive result should prompt avoidance of allopurinol, but a negative result does not preclude its use, so blanket avoidance without testing is not the recommended approach.', 2),
('df000000-0000-0000-0000-000000000015', 'C', 'Perform a formal allopurinol drug challenge test in a monitored setting', false, 'Ruled out because there is no standard practice of a monitored drug challenge for allopurinol; the appropriate risk-mitigation strategy in this ethnic group is pre-treatment HLA-B*5801 genotyping, not a supervised challenge.', 3),
('df000000-0000-0000-0000-000000000015', 'D', 'Co-prescribe prophylactic antihistamines to reduce hypersensitivity risk', false, 'Ruled out because antihistamine prophylaxis has no established role in preventing allopurinol hypersensitivity syndrome, which is a severe, often delayed T-cell-mediated reaction; the evidence-based mitigation strategy is pre-treatment genetic screening in high-risk groups.', 4),
('df000000-0000-0000-0000-000000000015', 'E', 'Screen for the HLA-B*5801 allele before initiating allopurinol', true, 'Correct. HLA-B*5801 is strongly associated with severe allopurinol hypersensitivity syndrome, including Stevens-Johnson syndrome/toxic epidermal necrolysis, and is substantially more prevalent in individuals of Han Chinese, Thai, and Korean descent. Guidelines recommend screening for this allele in high-risk ethnic groups before starting allopurinol, and using an alternative urate-lowering agent (e.g. febuxostat, with appropriate caution regarding cardiovascular risk) if positive.', 5),
('df000000-0000-0000-0000-000000000016', 'A', 'Serum ceruloplasmin and 24-hour urinary copper', false, $x$Ruled out because these are relevant to the investigation of Wilson's disease, not to pre-treatment screening for pegloticase; they have no bearing on pegloticase safety.$x$, 1),
('df000000-0000-0000-0000-000000000016', 'B', 'HLA-B*5801 genotype', false, 'Ruled out because HLA-B*5801 is relevant to allopurinol hypersensitivity risk, not to pegloticase, which has a different mechanism of action (uricase enzyme replacement) unrelated to this genetic risk factor.', 2),
('df000000-0000-0000-0000-000000000016', 'C', 'G6PD (glucose-6-phosphate dehydrogenase) deficiency status', true, 'Correct. Pegloticase is a recombinant uricase that converts uric acid to allantoin, generating hydrogen peroxide as a by-product; in patients with G6PD deficiency, this can precipitate severe haemolysis and methaemoglobinaemia. G6PD deficiency screening is required before initiating pegloticase, and it is contraindicated in G6PD-deficient patients.', 3),
('df000000-0000-0000-0000-000000000016', 'D', 'Hepatitis B surface antigen and core antibody status', false, 'Ruled out because hepatitis B screening is relevant before starting biologic immunosuppressants that carry a reactivation risk (e.g. rituximab, TNF inhibitors), not before pegloticase, which is a non-immunosuppressive uricolytic enzyme with a different key safety concern (G6PD deficiency and infusion reactions).', 4),
('df000000-0000-0000-0000-000000000016', 'E', 'Baseline dual-energy CT of the affected joints', false, 'Ruled out because although dual-energy CT can help characterise urate crystal deposition, it is not a required safety screening test before starting pegloticase; the critical safety check is G6PD deficiency status due to the haemolysis risk.', 5),
('df000000-0000-0000-0000-000000000017', 'A', 'Stop furosemide to reduce serum urate, switching to an alternative antihypertensive for volume control', false, 'Ruled out because furosemide is being used for heart failure symptom/volume control, not simply as an antihypertensive, and stopping it risks precipitating decompensated heart failure; loop diuretics should be continued when clinically indicated for heart failure, with the resulting hyperuricaemia managed pharmacologically instead.', 1),
('df000000-0000-0000-0000-000000000017', 'B', 'Continue the furosemide for heart failure control and start allopurinol, titrating to target urate', true, 'Correct. Loop diuretics should not be stopped in a patient with symptomatic heart failure requiring them for volume control, as this would risk decompensation; the appropriate approach is to continue necessary heart failure therapy and treat the resulting hyperuricaemia directly with a urate-lowering agent such as allopurinol, titrated to target urate, rather than withdrawing diuretic therapy.', 2),
('df000000-0000-0000-0000-000000000017', 'C', 'Avoid urate-lowering therapy altogether because diuretic-induced hyperuricaemia does not benefit from treatment', false, 'Ruled out because diuretic-induced hyperuricaemia still responds to standard urate-lowering therapy (e.g. allopurinol) and recurrent flares in this context warrant treatment; the mechanism of hyperuricaemia does not preclude effective urate-lowering therapy.', 3),
('df000000-0000-0000-0000-000000000017', 'D', 'Add a further thiazide diuretic to improve heart failure symptom control', false, 'Ruled out because thiazide diuretics would further raise serum urate and worsen gout control, compounding the problem rather than addressing his heart failure or hyperuricaemia appropriately.', 4),
('df000000-0000-0000-0000-000000000017', 'E', 'Switch furosemide to losartan as a direct diuretic substitute for fluid management in heart failure', false, 'Ruled out because losartan is an angiotensin receptor blocker, not a diuretic, and cannot be used as a direct substitute for furosemide in managing fluid overload in heart failure; while losartan does have a modest uricosuric effect and may be a reasonable adjunct antihypertensive/HF agent, it does not replace the need for loop diuretic-based volume control here.', 5),
('df000000-0000-0000-0000-000000000018', 'A', 'Low-dose colchicine (or an NSAID if not contraindicated) for at least the first 3-6 months of urate-lowering therapy', true, 'Correct. Initiating or up-titrating urate-lowering therapy mobilises urate stores and paradoxically increases the risk of acute gout flares in the first months of treatment. Prophylactic low-dose colchicine (or an NSAID, if no contraindication) is recommended for at least 3-6 months from initiation/dose changes to reduce this risk, and should be continued for longer if flares continue or tophi are extensive.', 1),
('df000000-0000-0000-0000-000000000018', 'B', 'High-dose corticosteroids continuously for the first year of urate-lowering therapy', false, 'Ruled out because long-term high-dose corticosteroids carry substantial cumulative toxicity and are not the recommended prophylactic strategy during ULT initiation; low-dose colchicine or NSAID prophylaxis for a defined period (typically 3-6 months) is preferred.', 2),
('df000000-0000-0000-0000-000000000018', 'C', 'No prophylaxis is required as allopurinol itself has anti-inflammatory properties', false, 'Ruled out because allopurinol has no anti-inflammatory action; it is a xanthine oxidase inhibitor that lowers urate synthesis, and initiating it can transiently increase flare risk through urate mobilisation, which is why prophylaxis is recommended.', 3),
('df000000-0000-0000-0000-000000000018', 'D', 'Discontinue allopurinol immediately if any flare occurs during the titration period', false, 'Ruled out because flares occurring during dose titration do not necessitate stopping urate-lowering therapy; with adequate prophylactic cover, allopurinol should be continued and titrated to target, as flares during this period are an expected phenomenon related to urate mobilisation, not treatment failure.', 4),
('df000000-0000-0000-0000-000000000018', 'E', 'Delay any anti-inflammatory prophylaxis until after a flare has already occurred', false, 'Ruled out because prophylaxis is intended to be started proactively alongside initiation of urate-lowering therapy, precisely to reduce the incidence of flares during the mobilisation period, rather than reactively after a flare has already developed.', 5),
('df000000-0000-0000-0000-000000000019', 'A', 'Manage as idiopathic CPPD with NSAIDs alone, as this is the most common cause at any age', false, 'Ruled out because although idiopathic (age-related) CPPD is the most common cause overall, young-onset CPPD (as in this 39-year-old) warrants specific evaluation for underlying metabolic disease; she already has known primary hyperparathyroidism, a recognised secondary cause, which should be optimally managed as part of her overall care.', 1),
('df000000-0000-0000-0000-000000000019', 'B', 'Arrange genetic testing for ANKH mutations as the first-line investigation', false, 'Ruled out because although rare familial CPPD (associated with ANKH mutations) exists, it is not the first-line investigation in a patient with an already-identified secondary metabolic cause (hyperparathyroidism); acquired metabolic causes should be evaluated and addressed first.', 2),
('df000000-0000-0000-0000-000000000019', 'C', 'Reassure that chondrocalcinosis is an incidental radiographic finding requiring no further action', false, 'Ruled out because in this context (young age, recurrent symptomatic CPPD, known hyperparathyroidism), chondrocalcinosis is not incidental; it reflects true crystal deposition disease requiring evaluation of underlying secondary causes and symptomatic joint management.', 3),
('df000000-0000-0000-0000-000000000019', 'D', 'Screen for underlying metabolic disease, including serum calcium, PTH, magnesium, ferritin, and transferrin saturation', true, 'Correct. CPPD occurring in a relatively young patient (under approximately 55 years), especially with polyarticular or unusual joint distribution, should prompt screening for an underlying metabolic driver, including primary hyperparathyroidism (as already identified here), haemochromatosis, hypomagnesaemia, and hypophosphatasia. Identifying and treating the underlying metabolic cause is important, as CPPD can be a presenting feature of these conditions.', 4),
('df000000-0000-0000-0000-000000000019', 'E', 'Start allopurinol to reduce crystal deposition', false, 'Ruled out because allopurinol lowers urate and has no role in calcium pyrophosphate deposition disease, which is a distinct crystal arthropathy unrelated to purine metabolism.', 5),
('df000000-0000-0000-0000-000000000020', 'A', 'Treat empirically as a gout flare with colchicine, given his known history of gout', false, 'Ruled out because a hot swollen prosthetic joint should never be assumed to be a gout flare based on history alone; prosthetic joint infection must be actively excluded first with aspiration, as missing infection in a prosthetic joint has serious consequences.', 1),
('df000000-0000-0000-0000-000000000020', 'B', 'Start empirical broad-spectrum antibiotics immediately without joint aspiration', false, 'Ruled out because starting antibiotics before aspiration risks sterilising cultures and reducing diagnostic yield; unless the patient is septic and unstable, aspiration should be obtained first to guide targeted therapy and confirm or exclude infection.', 2),
('df000000-0000-0000-0000-000000000020', 'C', 'Arrange elective outpatient rheumatology review in the next few weeks', false, 'Ruled out because an acutely hot, swollen prosthetic joint with fever represents a potential surgical emergency (possible prosthetic joint infection) that requires urgent same-day assessment and joint aspiration, not deferred outpatient review.', 3),
('df000000-0000-0000-0000-000000000020', 'D', 'Give an intra-articular corticosteroid injection to settle presumed inflammatory flare', false, 'Ruled out because intra-articular steroid injection into a potentially infected prosthetic joint is contraindicated, as it risks seeding or worsening infection; this must be excluded first.', 4),
('df000000-0000-0000-0000-000000000020', 'E', 'Urgent orthopaedic referral for joint aspiration before starting any antibiotics', true, 'Correct. An acutely hot, swollen prosthetic joint must be treated as a possible prosthetic joint infection until proven otherwise, given the potentially devastating consequences of a missed periprosthetic infection (need for revision surgery, sepsis, limb loss of function). Aspiration for synovial fluid analysis, crystal examination, Gram stain and culture should be obtained urgently before starting antibiotics, even though this patient has a prior history of gout, since gout and prosthetic joint infection can present very similarly and gout does not exclude concurrent infection.', 5),
('df000000-0000-0000-0000-000000000021', 'A', 'Check varicella zoster IgG status only, as this is the main infection risk with anti-TNF therapy', false, 'Ruled out because although reactivation of varicella zoster (shingles) can occur with immunosuppression generally, the specific and mandatory pre-biologic screening requirement for anti-TNF therapy is for latent tuberculosis, given its recognised risk of reactivation and disseminated disease with TNF blockade.', 1),
('df000000-0000-0000-0000-000000000021', 'B', 'No specific screening is required if the patient is asymptomatic and has a normal chest examination', false, 'Ruled out because latent TB is by definition asymptomatic with a normal examination; screening with IGRA and chest radiograph is required regardless of symptoms before starting anti-TNF therapy, as clinical assessment alone is inadequate to exclude latent infection.', 2),
('df000000-0000-0000-0000-000000000021', 'C', 'Perform a tuberculin skin test only, without an interferon-gamma release assay or chest radiograph', false, 'Ruled out because current UK practice (NICE/BTS) uses interferon-gamma release assays (which are not confounded by prior BCG vaccination) alongside chest radiography for pre-biologic TB screening; skin testing alone is not the recommended sole approach.', 3),
('df000000-0000-0000-0000-000000000021', 'D', 'Screen for latent tuberculosis with an interferon-gamma release assay and chest radiograph', true, 'Correct. Anti-TNF therapy can reactivate latent tuberculosis infection, which can present atypically and disseminate in this context. Screening with an interferon-gamma release assay (e.g. QuantiFERON) and chest radiograph is mandatory before starting anti-TNF therapy, with treatment of latent TB (if identified) generally required before or alongside starting the biologic.', 4),
('df000000-0000-0000-0000-000000000021', 'E', 'Delay TB screening until after starting the biologic, and monitor clinically for signs of infection', false, 'Ruled out because TB screening must be performed before starting anti-TNF therapy, not after; if latent TB is identified, treatment is generally initiated before or concurrently with the biologic to reduce reactivation risk.', 5),
('df000000-0000-0000-0000-000000000022', 'A', 'Continue methotrexate throughout pregnancy since her disease is currently well controlled', false, 'Ruled out because methotrexate is teratogenic (associated with fetal malformations and pregnancy loss) and must be stopped well before conception regardless of current disease control; continuing it into pregnancy is contraindicated.', 1),
('df000000-0000-0000-0000-000000000022', 'B', 'Stop all disease-modifying therapy, including adalimumab, at least 6 months before conception to eliminate any drug exposure', false, 'Ruled out because stopping all therapy risks a significant disease flare during pregnancy, which itself carries maternal and fetal risks; the preferred approach is to switch to a pregnancy-compatible biologic (certolizumab pegol) to maintain disease control while stopping methotrexate.', 2),
('df000000-0000-0000-0000-000000000022', 'C', 'Stop methotrexate at least 3 months before conception; switch adalimumab to certolizumab pegol, which can be continued throughout pregnancy', true, 'Correct. Methotrexate is teratogenic and must be discontinued at least 3 months before conception. Among anti-TNF agents, certolizumab pegol has minimal to no active placental transfer (due to lack of an Fc region) and is considered the anti-TNF of choice to continue throughout pregnancy in women who require ongoing biologic therapy to maintain disease control, reducing the risk of a disease flare during pregnancy.', 3),
('df000000-0000-0000-0000-000000000022', 'D', 'Switch adalimumab to a JAK inhibitor to allow continued disease control during pregnancy', false, 'Ruled out because JAK inhibitors are not recommended in pregnancy due to limited safety data and preclinical concerns; this would not be an appropriate substitute for anti-TNF therapy in a woman planning pregnancy.', 4),
('df000000-0000-0000-0000-000000000022', 'E', 'Continue adalimumab unchanged and add certolizumab pegol as combination biologic therapy for pregnancy', false, 'Ruled out because there is no indication or evidence base for combining two anti-TNF biologics; the correct approach is to switch (not add) to certolizumab pegol, which is preferred due to its lack of significant placental transfer.', 5),
('df000000-0000-0000-0000-000000000023', 'A', 'Rituximab', true, 'Correct. Rituximab (anti-CD20) is itself used as a treatment for B-cell lymphomas and has not been associated with an increased risk of malignancy recurrence; it is generally considered a reasonable, and often preferred, biologic choice in RA patients with a history of lymphoma, in contrast to some historical caution around TNF inhibitors and malignancy risk in this context.', 1),
('df000000-0000-0000-0000-000000000023', 'B', 'Adalimumab', false, 'Ruled out as first choice here because although the evidence for anti-TNF agents and malignancy recurrence risk is not entirely consistent, TNF inhibitors have historically been used with more caution in patients with a prior lymphoma, and rituximab (which is itself an anti-lymphoma therapy) represents a more clearly favourable choice in this specific context.', 2),
('df000000-0000-0000-0000-000000000023', 'C', 'Tofacitinib', false, 'Ruled out as first choice here because JAK inhibitors carry warnings regarding malignancy risk (alongside VTE and MACE) from long-term surveillance data, making them a less preferable choice in a patient with a significant prior malignancy history when other effective and better-suited options (rituximab) exist.', 3),
('df000000-0000-0000-0000-000000000023', 'D', 'Etanercept', false, 'Ruled out as first choice here for the same reason as adalimumab: anti-TNF agents have historically been used more cautiously in patients with prior lymphoma, whereas rituximab is a more directly favourable option given its role in treating B-cell lymphomas.', 4),
('df000000-0000-0000-0000-000000000023', 'E', 'Abatacept as an alternative to a B-cell or T-cell targeted approach is contraindicated in all patients with any cancer history', false, $x$Ruled out because this statement is factually incorrect — abatacept is not universally contraindicated in patients with any cancer history; while individualised risk assessment is always needed, this option's blanket claim is not accurate and rituximab remains the preferred choice described above.$x$, 5),
('df000000-0000-0000-0000-000000000024', 'A', 'Proceed with tofacitinib at a reduced dose to mitigate VTE risk', false, 'Ruled out because dose reduction does not eliminate the elevated VTE/MACE risk associated with JAK inhibitors in high-risk patients; current guidance recommends avoiding this drug class altogether in patients with significant pre-existing VTE or cardiovascular risk factors, rather than simply reducing the dose.', 1),
('df000000-0000-0000-0000-000000000024', 'B', 'Start tofacitinib alongside prophylactic-dose anticoagulation to prevent recurrent VTE', false, 'Ruled out because routine prophylactic anticoagulation is not an established or recommended strategy to permit JAK inhibitor use in high VTE-risk patients; the appropriate action is to avoid the drug class in this population, not to add anticoagulation to mitigate the risk.', 2),
('df000000-0000-0000-0000-000000000024', 'C', 'Proceed with tofacitinib, as her rheumatoid arthritis activity outweighs the VTE risk concerns', false, 'Ruled out because regulatory and guideline bodies specifically advise against JAK inhibitor use in patients with significant VTE or cardiovascular risk factors irrespective of disease activity, given the demonstrated increased risk of serious thrombotic and cardiovascular events; alternative effective therapies exist and should be used instead.', 3),
('df000000-0000-0000-0000-000000000024', 'D', 'Switch to a second anti-TNF agent instead, as this class carries the same VTE risk as JAK inhibitors', false, 'Ruled out because this statement is inaccurate; TNF inhibitors were the comparator arm in the ORAL Surveillance trial and were associated with a lower risk of VTE and MACE than tofacitinib, so the two classes do not carry equivalent risk in this respect (though switching biologic class after one TNF inhibitor failure is reasonable on other therapeutic grounds).', 4),
('df000000-0000-0000-0000-000000000024', 'E', 'Avoid tofacitinib given her VTE and cardiovascular risk factors; consider an alternative mechanism such as a further biologic (e.g. rituximab or abatacept)', true, 'Correct. The ORAL Surveillance trial demonstrated an increased risk of venous thromboembolism and major adverse cardiovascular events with tofacitinib (and this is now considered a class effect across JAK inhibitors) compared with TNF inhibitors, particularly in patients aged 50 and over with at least one additional cardiovascular risk factor. This patient has significant risk factors (smoking, prior unprovoked VTE), so JAK inhibitors should be avoided in favour of an alternative biologic with a different mechanism of action.', 5),
('df000000-0000-0000-0000-000000000025', 'A', 'Proceed directly to splenectomy as first-line treatment', false, $x$Ruled out because splenectomy is not first-line management for Felty's syndrome; it is reserved for patients with recurrent severe infections or bleeding refractory to optimisation of disease-modifying therapy, given the surgical risks and the fact that neutropenia often improves with adequate control of RA disease activity.$x$, 1),
('df000000-0000-0000-0000-000000000025', 'B', 'Optimise disease-modifying therapy with methotrexate to control underlying rheumatoid disease activity', true, $x$Correct. This presentation (long-standing seropositive RA, splenomegaly, and neutropenia with normal marrow cellularity) is classic for Felty's syndrome. Effective control of the underlying RA disease activity, particularly with methotrexate, is first-line management and is often effective in improving the neutrophil count, as the neutropenia is closely linked to disease activity; splenectomy is reserved for cases refractory to medical therapy or complicated by severe recurrent infection or symptomatic hypersplenism.$x$, 2),
('df000000-0000-0000-0000-000000000025', 'C', 'Start granulocyte colony-stimulating factor (G-CSF) as monotherapy without addressing underlying RA control', false, 'Ruled out because although G-CSF can be used adjunctively in severe or refractory neutropenia with active infection, it does not address the underlying disease process, and can theoretically exacerbate joint inflammation; the first-line approach is to optimise disease-modifying therapy for the underlying RA.', 3),
('df000000-0000-0000-0000-000000000025', 'D', 'Stop all disease-modifying therapy given the risk of worsening neutropenia with immunosuppression', false, $x$Ruled out because withdrawing DMARD therapy would be expected to worsen, not improve, the neutropenia in Felty's syndrome, since neutropenia here is linked to uncontrolled RA disease activity rather than being a drug-induced cytopenia in this scenario.$x$, 4),
('df000000-0000-0000-0000-000000000025', 'E', 'Perform bone marrow transplantation as the definitive treatment', false, $x$Ruled out because bone marrow transplantation has no established role in the management of Felty's syndrome; this is a disease of immune dysregulation associated with RA activity, not a primary marrow failure state requiring transplantation.$x$, 5),
('df000000-0000-0000-0000-000000000026', 'A', 'Start empirical broad-spectrum antibiotics for presumed occult sepsis', false, $x$Ruled out because blood and throat cultures are already negative and the clinical pattern (quotidian fever, evanescent rash, very high ferritin, arthralgia) is characteristic of adult-onset Still's disease rather than an occult bacterial infection; further empirical antibiotics are not indicated at this stage.$x$, 1),
('df000000-0000-0000-0000-000000000026', 'B', 'Increase the NSAID dose further, having already tried high-dose NSAIDs without response', false, 'Ruled out because the patient has already failed an adequate trial of high-dose NSAIDs and corticosteroids; further dose escalation of NSAIDs is unlikely to achieve control and risks toxicity, whereas targeted biologic therapy (IL-1 blockade) is the appropriate escalation.', 2),
('df000000-0000-0000-0000-000000000026', 'C', 'Start an IL-1 inhibitor such as anakinra', true, $x$Correct. This presentation (quotidian high spiking fevers, evanescent salmon-pink rash, sore throat, arthralgia, markedly elevated ferritin, seronegative for RF/ANA, with infection excluded) is classic for adult-onset Still's disease. In patients with disease refractory to NSAIDs and corticosteroids, IL-1 blockade (e.g. anakinra) is highly effective and is an established next step, reflecting the central role of IL-1 in this condition's pathogenesis (part of the broader autoinflammatory disease spectrum).$x$, 3),
('df000000-0000-0000-0000-000000000026', 'D', 'Perform splenectomy for presumed haematological malignancy given the markedly elevated ferritin', false, $x$Ruled out because markedly elevated ferritin in this clinical context (fever pattern, rash, arthralgia, negative autoantibodies and cultures) is characteristic of adult-onset Still's disease (and should also prompt consideration of macrophage activation syndrome), not an indication for splenectomy or a sign specifically of malignancy without further evaluation.$x$, 4),
('df000000-0000-0000-0000-000000000026', 'E', 'Reassure and observe, as the condition is self-limiting and requires no specific treatment', false, $x$Ruled out because although some cases of adult-onset Still's disease can remit, this patient has ongoing significant symptoms refractory to first-line therapy, indicating a need for escalation of treatment (IL-1 blockade) rather than watchful observation alone, particularly given the risk of complications such as macrophage activation syndrome.$x$, 5),
('df000000-0000-0000-0000-000000000027', 'A', 'Hepatitis A IgM antibody', false, 'Ruled out because hepatitis A does not have a chronic carrier state or a recognised reactivation risk with immunosuppression in the way hepatitis B does; it is not the relevant screening test before starting rituximab.', 1),
('df000000-0000-0000-0000-000000000027', 'B', 'No specific viral screening is required if liver function tests are normal', false, 'Ruled out because normal liver function tests do not exclude past or chronic hepatitis B infection (including inactive carriers or those with resolved infection who remain at risk of reactivation); specific serological screening (HBsAg, anti-HBc) is required regardless of baseline LFTs.', 2),
('df000000-0000-0000-0000-000000000027', 'C', 'Hepatitis C RNA only, as this is the main viral reactivation risk with rituximab', false, 'Ruled out because although hepatitis C should also be considered in appropriate epidemiological contexts, the well-established and specifically significant reactivation risk with B-cell depleting therapy like rituximab is hepatitis B, not hepatitis C; HBsAg/anti-HBc screening is the key required test.', 3),
('df000000-0000-0000-0000-000000000027', 'D', 'Hepatitis B surface antigen and core antibody (HBsAg and anti-HBc)', true, 'Correct. Rituximab (and B-cell depleting therapy more broadly) carries a significant risk of hepatitis B reactivation, including in patients with resolved past infection (HBsAg negative, anti-HBc positive), which can result in severe or fulminant hepatitis. Screening with HBsAg and anti-HBc is required before starting rituximab, with antiviral prophylaxis or close monitoring instituted according to the results.', 4),
('df000000-0000-0000-0000-000000000027', 'E', 'HIV antibody testing alone, deferring hepatitis screening until after treatment starts', false, 'Ruled out because hepatitis B screening must be performed before, not after, starting rituximab, given the risk of severe reactivation hepatitis; while HIV status may also be relevant to overall risk assessment, it does not substitute for pre-treatment hepatitis B screening.', 5),
('df000000-0000-0000-0000-000000000028', 'A', 'Colchicine as monotherapy, as used in familial Mediterranean fever-associated amyloidosis', false, $x$Ruled out because colchicine's established role in preventing AA amyloidosis is specific to autoinflammatory periodic fever syndromes such as familial Mediterranean fever; in rheumatoid arthritis-associated AA amyloidosis, the priority is aggressive suppression of the underlying rheumatoid inflammatory activity, not colchicine monotherapy.$x$, 1),
('df000000-0000-0000-0000-000000000028', 'B', 'Aggressive suppression of the underlying inflammatory disease activity, using an agent that effectively lowers serum amyloid A (e.g. tocilizumab)', true, 'Correct. This is secondary (AA) amyloidosis complicating long-standing, poorly controlled rheumatoid arthritis, driven by chronically elevated serum amyloid A protein. Management centres on aggressively suppressing the underlying inflammatory disease activity to reduce serum amyloid A production; IL-6 pathway blockade (e.g. tocilizumab) is particularly effective at lowering serum amyloid A levels and has demonstrated benefit in AA amyloidosis, making it an appropriate targeted choice in this context.', 2),
('df000000-0000-0000-0000-000000000028', 'C', 'Renal transplantation without addressing the underlying rheumatoid disease activity', false, 'Ruled out because transplantation without controlling the underlying inflammatory drive would risk recurrent AA amyloid deposition in the transplanted kidney; effective suppression of the underlying disease is a prerequisite for any consideration of transplantation, not an alternative to it.', 3),
('df000000-0000-0000-0000-000000000028', 'D', 'High-dose corticosteroids alone as long-term maintenance therapy', false, 'Ruled out because although corticosteroids have anti-inflammatory effects, long-term high-dose corticosteroid monotherapy is not the preferred approach; targeted therapy that durably lowers serum amyloid A (such as IL-6 blockade) combined with appropriate disease-modifying therapy is more effective and carries less cumulative toxicity.', 4),
('df000000-0000-0000-0000-000000000028', 'E', 'Chemotherapy directed at plasma cell dyscrasia, as used in AL amyloidosis', false, 'Ruled out because the biopsy here confirms AA-type amyloid (secondary to chronic inflammation), not AL amyloid (associated with plasma cell dyscrasias); chemotherapy targeting plasma cells is the treatment approach for AL amyloidosis, not the AA amyloidosis described here.', 5),
('df000000-0000-0000-0000-000000000029', 'A', 'Anti-TNF agents (e.g. infliximab, adalimumab, etanercept)', true, 'Correct. Anti-TNF agents are relatively contraindicated in patients with moderate-to-severe heart failure (NYHA class III-IV), as clinical trials found worsening heart failure and increased mortality with TNF inhibition in this population (particularly with infliximab at higher doses). Alternative-mechanism biologics such as rituximab or abatacept are preferred in patients with significant heart failure.', 1),
('df000000-0000-0000-0000-000000000029', 'B', 'IL-6 receptor inhibitors (e.g. tocilizumab) are absolutely contraindicated in all cardiac disease and must never be used', false, 'Ruled out because this is an overly absolute and inaccurate statement; tocilizumab does not carry the same specific heart failure contraindication as anti-TNF therapy, though it requires its own monitoring (e.g. for hyperlipidaemia). It is anti-TNF agents, not IL-6 inhibitors as a class, that are specifically cautioned against in significant heart failure.', 2),
('df000000-0000-0000-0000-000000000029', 'C', 'B-cell depleting therapy (rituximab) is contraindicated in heart failure', false, 'Ruled out because rituximab does not carry a specific heart failure contraindication and is often considered a reasonable alternative biologic choice in patients with significant cardiac disease where anti-TNF therapy is avoided.', 3),
('df000000-0000-0000-0000-000000000029', 'D', 'T-cell costimulation blockade (abatacept) is contraindicated in heart failure', false, 'Ruled out because abatacept does not carry the same heart failure-specific contraindication seen with anti-TNF agents and is often considered a reasonable option when TNF inhibitors are avoided for this reason.', 4),
('df000000-0000-0000-0000-000000000029', 'E', 'JAK inhibitors are the only biologic class safe to use in heart failure', false, 'Ruled out because JAK inhibitors are not specifically indicated as the safe choice in heart failure; rather, they carry their own separate safety concerns (VTE and major adverse cardiovascular events), and would require careful individualised risk assessment, not blanket preference, in a patient with significant cardiac disease.', 5),
('df000000-0000-0000-0000-000000000030', 'A', 'Continue methotrexate at the same dose and add prophylactic co-trimoxazole', false, 'Ruled out because if this represents methotrexate-induced pneumonitis, continuing the drug risks further, potentially fatal, lung injury; methotrexate should be stopped immediately while the diagnosis is clarified, rather than continued alongside prophylaxis for a different (infective) process.', 1),
('df000000-0000-0000-0000-000000000030', 'B', 'Reduce the methotrexate dose by half and monitor symptoms over the next 2 weeks', false, $x$Ruled out because dose reduction alone is not an adequate response to suspected methotrexate pneumonitis, which requires immediate cessation of the drug given its potential severity; a 'wait and monitor' approach with a reduced dose risks clinical deterioration.$x$, 2),
('df000000-0000-0000-0000-000000000030', 'C', 'Start empirical broad-spectrum antibiotics only, without stopping methotrexate or considering pneumonitis', false, 'Ruled out because this fails to consider methotrexate pneumonitis as a differential diagnosis, which requires prompt drug cessation; treating only for infection while continuing a potentially causative drug risks worsening a non-infective pneumonitis.', 3),
('df000000-0000-0000-0000-000000000030', 'D', 'Arrange outpatient high-resolution CT in 4-6 weeks with no change to current therapy in the interim', false, 'Ruled out because this patient has hypoxia and new bilateral changes with progressive symptoms, indicating a need for urgent (not delayed outpatient) assessment; methotrexate should be stopped immediately pending investigation, not continued for weeks before imaging is even performed.', 4),
('df000000-0000-0000-0000-000000000030', 'E', 'Stop methotrexate immediately, investigate promptly to distinguish methotrexate-induced pneumonitis from infection (including atypical/opportunistic pathogens), and start high-dose corticosteroids if pneumonitis is confirmed or strongly suspected', true, 'Correct. Methotrexate pneumonitis is a recognised, potentially life-threatening idiosyncratic reaction that can occur at any point during treatment and presents with subacute dyspnoea, dry cough, fever, and bilateral ground-glass changes — a picture that overlaps significantly with atypical or opportunistic infection in an immunosuppressed patient. The correct approach is to stop methotrexate immediately (as continuing it in true pneumonitis risks rapid deterioration), pursue prompt investigation (including looking for infection, e.g. PCP, given the immunosuppressed state), and start high-dose corticosteroids if pneumonitis is confirmed or remains the leading diagnosis after appropriate work-up.', 5),
('df000000-0000-0000-0000-000000000031', 'A', 'Start methotrexate for axial disease control', false, 'Ruled out because conventional synthetic DMARDs such as methotrexate and sulfasalazine have not shown efficacy for axial (spinal/sacroiliac) disease in ankylosing spondylitis, even though they may have a role in peripheral arthritis; biologic therapy is the appropriate escalation for refractory axial disease.', 1),
('df000000-0000-0000-0000-000000000031', 'B', 'Continue the same NSAID regimen for a further 6 months before considering any escalation', false, 'Ruled out because an adequate trial of NSAID therapy (typically at least two agents at maximum dose over 2-4 weeks each, which has already been exceeded here at 3 months) with inadequate response is sufficient to justify escalation to biologic therapy; further prolonged NSAID trial is not required before proceeding.', 2),
('df000000-0000-0000-0000-000000000031', 'C', 'Refer for surgical spinal fusion given ongoing symptoms', false, 'Ruled out because surgical intervention is reserved for specific structural complications (e.g. severe deformity, fracture) in ankylosing spondylitis, not for escalation of medical therapy in a patient with active inflammatory disease who has not yet trialled biologic therapy.', 3),
('df000000-0000-0000-0000-000000000031', 'D', 'Start long-term oral corticosteroids for disease control', false, 'Ruled out because oral corticosteroids have limited efficacy for axial disease in ankylosing spondylitis and are associated with significant cumulative toxicity with long-term use; they are not an appropriate strategy for ongoing disease control in this context.', 4),
('df000000-0000-0000-0000-000000000031', 'E', 'Start an anti-TNF biologic agent', true, $x$Correct. In axial spondyloarthritis/ankylosing spondylitis with persistently active disease (elevated BASDAI, objective MRI evidence of active sacroiliitis) despite an adequate trial of at least two NSAIDs at maximum tolerated dose, biologic therapy (anti-TNF, or alternatively an IL-17 inhibitor) is indicated as the next step, per NICE/ASAS-EULAR recommendations, given the lack of a synthetic DMARD's proven efficacy for axial disease.$x$, 5),
('df000000-0000-0000-0000-000000000032', 'A', 'IL-17 inhibitors (e.g. secukinumab, ixekizumab)', true, $x$Correct. IL-17 inhibitors have been associated with new onset or exacerbation of inflammatory bowel disease, and should generally be avoided in patients with coexisting or a history of IBD such as Crohn's disease. An anti-TNF agent (which treats both joint and bowel disease) or an IL-12/23 inhibitor (e.g. ustekinumab) is preferred in this context.$x$, 1),
('df000000-0000-0000-0000-000000000032', 'B', 'Anti-TNF agents (e.g. adalimumab, infliximab)', false, $x$Ruled out because anti-TNF agents are generally an appropriate and often preferred choice in patients with both psoriatic arthritis and Crohn's disease, as they have established efficacy for both conditions; this is not the class that should be avoided here.$x$, 2),
('df000000-0000-0000-0000-000000000032', 'C', 'IL-12/23 inhibitors (e.g. ustekinumab)', false, 'Ruled out because IL-12/23 inhibitors do not carry the same risk of IBD exacerbation as IL-17 inhibitors and are a reasonable alternative option in patients with coexisting IBD; this is not the class to avoid.', 3),
('df000000-0000-0000-0000-000000000032', 'D', 'JAK inhibitors', false, 'Ruled out because although JAK inhibitors have their own distinct safety considerations (VTE, MACE, malignancy), they are not specifically the class most classically associated with precipitating or worsening IBD in this way; IL-17 inhibitors carry that specific concern.', 4),
('df000000-0000-0000-0000-000000000032', 'E', $x$Methotrexate should also be avoided in Crohn's disease$x$, false, $x$Ruled out because methotrexate is not contraindicated in Crohn's disease and does not carry a recognised risk of exacerbating IBD; this option incorrectly extends the concern to a drug where it does not apply, whereas the biologic class of specific concern here is IL-17 inhibition.$x$, 5),
('df000000-0000-0000-0000-000000000033', 'A', 'Antibiotics alone are sufficient, as treating the chlamydial infection will resolve the arthritis without additional joint-directed treatment', false, 'Ruled out because although treating the underlying infection is important, the reactive arthritis itself is an immune-mediated sterile inflammatory process that often requires separate symptomatic treatment (NSAIDs, intra-articular steroids) and does not necessarily resolve quickly with antibiotics alone.', 1),
('df000000-0000-0000-0000-000000000033', 'B', 'Start empirical intravenous antibiotics for the knee, treating it as septic arthritis, given the joint swelling', false, 'Ruled out because joint aspiration has already demonstrated a sterile effusion with no organisms; this is reactive (immune-mediated), not septic, arthritis, so treatment should be directed at the underlying trigger and symptomatic joint management, not intravenous antibiotics for a presumed joint infection.', 2),
('df000000-0000-0000-0000-000000000033', 'C', 'Treat the underlying chlamydial infection with appropriate antibiotics (e.g. azithromycin or doxycycline), ensure partner notification and treatment, and manage the joint symptoms with NSAIDs and/or intra-articular corticosteroid injection', true, 'Correct. This presentation (asymmetric oligoarthritis, conjunctivitis, and mucocutaneous lesions following genitourinary chlamydial infection) is classic reactive arthritis. Management includes treating the triggering chlamydial infection with appropriate antibiotics and ensuring partner notification/treatment (as chlamydia is sexually transmitted and can persist/reinfect), alongside symptomatic treatment of the sterile reactive arthritis itself with NSAIDs and/or intra-articular corticosteroids, since antibiotics alone do not rapidly resolve the arthritis (which is immune-mediated, not an active joint infection).', 3),
('df000000-0000-0000-0000-000000000033', 'D', 'No antibiotic treatment is required since the arthritis itself is sterile and the acute urethral symptoms have already resolved', false, 'Ruled out because the underlying chlamydial infection should still be treated even though the joint is sterile, both to eradicate ongoing infection and reduce the risk of complications/transmission; partner notification and treatment are also required given the sexually transmitted nature of the trigger.', 4),
('df000000-0000-0000-0000-000000000033', 'E', 'Start a biologic anti-TNF agent immediately as first-line therapy for the arthritis', false, 'Ruled out because biologic therapy is reserved for chronic or relapsing reactive arthritis refractory to NSAIDs/DMARDs, not as first-line treatment for an acute, likely self-limiting presentation; initial management should focus on treating the trigger and symptomatic control.', 5),
('df000000-0000-0000-0000-000000000034', 'A', 'Etanercept, given its established efficacy for axial disease', false, $x$Ruled out because although etanercept is effective for axial disease, it is less effective at preventing uveitis flares than monoclonal anti-TNF antibodies and has even been associated with new-onset uveitis in some patients; it would not be the preferred choice given this patient's recurrent uveitis.$x$, 1),
('df000000-0000-0000-0000-000000000034', 'B', 'An IL-17 inhibitor as first-line biologic given its efficacy for axial disease', false, 'Ruled out because IL-17 inhibitors, while effective for axial disease, have been associated with new-onset uveitis in some studies and do not have the same specific evidence base for uveitis prevention as monoclonal anti-TNF antibodies; in a patient with recurrent uveitis specifically, monoclonal anti-TNF therapy is preferred.', 2),
('df000000-0000-0000-0000-000000000034', 'C', 'Topical corticosteroids alone, escalating dose and frequency, without any systemic biologic therapy', false, 'Ruled out because this patient has poorly controlled axial disease requiring systemic biologic therapy regardless of the uveitis; relying on topical treatment alone fails to address the systemic inflammatory disease driving both his axial symptoms and recurrent uveitis.', 3),
('df000000-0000-0000-0000-000000000034', 'D', 'A monoclonal anti-TNF antibody such as adalimumab, rather than etanercept', true, 'Correct. Monoclonal anti-TNF antibodies (adalimumab, infliximab, golimumab) have demonstrated greater efficacy in reducing the recurrence of acute anterior uveitis compared with etanercept, which is a soluble TNF receptor fusion protein and has been associated with a higher rate of uveitis flares (and, in some cases, new-onset uveitis) despite adequately treating axial symptoms. In a patient with both active axial disease and recurrent uveitis, a monoclonal anti-TNF antibody is therefore the preferred choice.', 4),
('df000000-0000-0000-0000-000000000034', 'E', 'Oral corticosteroids as maintenance therapy to reduce uveitis recurrence and control axial symptoms', false, 'Ruled out because long-term oral corticosteroids are not an appropriate maintenance strategy for either axial spondyloarthritis or recurrent uveitis, given cumulative toxicity, and targeted biologic therapy is a more effective and guideline-supported approach.', 5),
('df000000-0000-0000-0000-000000000035', 'A', 'Continue the NSAID as it is an effective and first-line treatment for the peripheral arthritis', false, 'Ruled out because although NSAIDs are typically first-line for peripheral arthritis in seronegative spondyloarthropathy generally, they carry a specific risk of exacerbating inflammatory bowel disease and should be used cautiously, if at all, and stopped if bowel symptoms worsen, as appears to be occurring here.', 1),
('df000000-0000-0000-0000-000000000035', 'B', 'Stop the NSAID, as it is likely contributing to her worsening bowel symptoms, and use alternative analgesia (e.g. paracetamol) alongside optimisation of disease-modifying/biologic therapy for both joint and bowel disease', true, 'Correct. NSAIDs are relatively contraindicated in inflammatory bowel disease, as they can precipitate or worsen disease flares through effects on the gut mucosa. In a patient with enteropathic (IBD-associated) arthritis and worsening bowel symptoms coinciding with regular NSAID use, the NSAID should be stopped, with joint symptoms managed through alternative analgesia and treatment directed at the underlying IBD/arthritis (e.g. anti-TNF therapy, which treats both), rather than continued NSAID use.', 2),
('df000000-0000-0000-0000-000000000035', 'C', 'Switch to a different NSAID class (e.g. a COX-2 selective agent) rather than stopping NSAID therapy altogether', false, 'Ruled out because although COX-2 selective agents may carry a somewhat lower GI mucosal risk than non-selective NSAIDs, they are not free of the risk of exacerbating IBD, and in a patient with an apparent temporal link between NSAID use and worsening bowel symptoms, the safest approach is to stop NSAID therapy altogether rather than substitute another agent in the same class.', 3),
('df000000-0000-0000-0000-000000000035', 'D', 'Increase the NSAID dose to better control the joint symptoms, and manage the bowel flare separately with corticosteroids', false, 'Ruled out because increasing NSAID exposure would be expected to further worsen, not help, the underlying IBD flare; the appropriate response to a probable NSAID-associated flare is to stop the NSAID, not increase its dose while treating the flare as an unrelated issue.', 4),
('df000000-0000-0000-0000-000000000035', 'E', 'Add a proton pump inhibitor to allow safe continuation of the NSAID', false, 'Ruled out because proton pump inhibitors mitigate NSAID-related upper GI mucosal injury (e.g. peptic ulceration) but do not protect against NSAID-associated exacerbation of inflammatory bowel disease occurring more distally in the gut; this would not resolve the underlying problem here.', 5),
('df000000-0000-0000-0000-000000000036', 'A', 'Reassure and discharge given a normal plain radiograph and normal neurological examination', false, 'Ruled out because plain radiographs have a well-recognised high false-negative rate for detecting fractures through an ankylosed spine, and normal initial neurology does not exclude an unstable fracture at risk of delayed neurological deterioration; further imaging (CT/MRI) is mandatory in this high-risk scenario before discharge can be considered.', 1),
('df000000-0000-0000-0000-000000000036', 'B', 'Arrange outpatient MRI in the next 1-2 weeks if pain persists', false, 'Ruled out because a possible unstable spinal fracture in an ankylosed spine, with associated risk of spinal cord injury, requires urgent (same-admission) imaging and immobilisation, not deferred outpatient assessment; delay risks catastrophic neurological injury.', 2),
('df000000-0000-0000-0000-000000000036', 'C', 'Urgent CT (or MRI) of the spine, treating this as a probable fracture despite a normal plain radiograph, with spinal immobilisation in the meantime', true, 'Correct. In a fused, ankylosed spine (as in long-standing ankylosing spondylitis), even minor trauma can cause an unstable fracture through the rigid spinal column, and such fractures are frequently missed or poorly visualised on plain radiographs due to altered anatomy and superimposed bony fusion. Because these fractures carry a high risk of spinal cord injury (including delayed neurological deterioration) even when initial neurology is normal, urgent CT (often preferred over plain film in this context) or MRI is required, with spinal immobilisation maintained until this is excluded, regardless of a reportedly normal plain radiograph.', 3),
('df000000-0000-0000-0000-000000000036', 'D', 'Prescribe analgesia and mobilise as tolerated, repeating the radiograph only if symptoms worsen', false, 'Ruled out because mobilising a patient with a possible unstable spinal fracture in an ankylosed spine risks converting a stable injury into a displaced fracture with spinal cord injury; the spine should be immobilised and urgently further imaged, not mobilised on the assumption of a benign radiograph.', 4),
('df000000-0000-0000-0000-000000000036', 'E', 'Refer for elective outpatient orthopaedic review within the next month', false, 'Ruled out because this presentation requires urgent same-admission assessment and imaging given the high risk of an unstable fracture and spinal cord injury in an ankylosed spine after trauma; elective, delayed referral is inappropriate.', 5),
('df000000-0000-0000-0000-000000000037', 'A', 'Methotrexate as first-line therapy for the axial symptoms', false, 'Ruled out because methotrexate (and other conventional synthetic DMARDs) has not demonstrated efficacy for axial disease in psoriatic arthritis, similar to its lack of efficacy in ankylosing spondylitis; it may have a role for peripheral arthritis or skin disease but not for axial symptoms.', 1),
('df000000-0000-0000-0000-000000000037', 'B', 'Sulfasalazine as first-line therapy for the axial symptoms', false, 'Ruled out for the same reason as methotrexate: sulfasalazine lacks proven efficacy for axial disease in spondyloarthropathy, even though it can be used for peripheral arthritis.', 2),
('df000000-0000-0000-0000-000000000037', 'C', 'Topical therapy for psoriasis alone, with no additional treatment needed for the joint symptoms', false, $x$Ruled out because this patient's joint symptoms (active sacroiliitis, dactylitis) require their own systemic treatment; topical skin therapy alone does not address axial or peripheral joint inflammation.$x$, 3),
('df000000-0000-0000-0000-000000000037', 'D', 'An anti-TNF biologic agent, following an inadequate response to NSAIDs', true, 'Correct. This patient has psoriatic arthritis with axial involvement (a recognised phenotype presenting similarly to ankylosing spondylitis, occurring in a subset of patients with psoriatic arthritis, particularly HLA-B27-associated cases). As with ankylosing spondylitis, axial disease in psoriatic arthritis that responds inadequately to NSAIDs is managed with biologic therapy (anti-TNF or IL-17 inhibition), as conventional synthetic DMARDs lack efficacy for axial disease.', 4),
('df000000-0000-0000-0000-000000000037', 'E', 'Long-term oral corticosteroids for both skin and axial disease control', false, 'Ruled out because oral corticosteroids have limited efficacy for axial disease and are also relatively avoided in psoriasis due to the risk of precipitating a severe flare (including pustular psoriasis) on withdrawal; this would not be appropriate management.', 5),
('df000000-0000-0000-0000-000000000038', 'A', $x$Continue secukinumab unchanged, as her axial disease remains well controlled, and treat the new Crohn's disease separately with a different agent$x$, false, 'Ruled out because continuing an agent that has been specifically implicated in causing or exacerbating her new inflammatory bowel disease risks ongoing gut inflammation; the appropriate approach is to switch away from the IL-17 inhibitor to an agent that treats both conditions, rather than continuing a likely causative drug alongside separate bowel treatment.', 1),
('df000000-0000-0000-0000-000000000038', 'B', 'Increase the secukinumab dose to also target the new bowel inflammation', false, $x$Ruled out because IL-17 inhibition has no efficacy for Crohn's disease and is specifically associated with causing or worsening IBD in some patients; increasing the dose would not address, and could worsen, the bowel disease.$x$, 2),
('df000000-0000-0000-0000-000000000038', 'C', 'Switch to a different IL-17 inhibitor (e.g. ixekizumab) as this may avoid the bowel complication', false, 'Ruled out because the risk of new-onset or exacerbated IBD is considered a class effect of IL-17 inhibition, not specific to secukinumab alone; switching within the same class would not be expected to resolve the problem, whereas switching to an anti-TNF agent addresses both conditions.', 3),
('df000000-0000-0000-0000-000000000038', 'D', $x$Refer for urgent colectomy without trialling medical therapy for the Crohn's disease$x$, false, $x$Ruled out because newly diagnosed Crohn's disease should be managed with medical therapy in the first instance (here, switching to an anti-TNF agent that treats both her joint and bowel disease); surgery is reserved for complications or medically refractory disease, not as an initial approach.$x$, 4),
('df000000-0000-0000-0000-000000000038', 'E', $x$Stop secukinumab and switch to an anti-TNF agent that also treats her Crohn's disease$x$, true, $x$Correct. IL-17 inhibitors (such as secukinumab) are associated with new-onset or exacerbation of inflammatory bowel disease, and this patient has developed new Crohn's disease while established on secukinumab. The IL-17 inhibitor should be stopped and she should be switched to an anti-TNF agent, which is effective for both her axial spondyloarthritis and the new Crohn's disease, addressing both conditions with a single, appropriate agent.$x$, 5),
('df000000-0000-0000-0000-000000000039', 'A', 'Reassure the patient that first-degree AV block is a benign finding requiring no further action', false, 'Ruled out because although first-degree AV block can be benign in the general population, in the context of HLA-B27-associated spondyloarthropathy with new symptoms (palpitations, pre-syncope), it should prompt evaluation for progressive conduction disease, which is a recognised complication of this condition and can progress to higher-grade block.', 1),
('df000000-0000-0000-0000-000000000039', 'B', 'Arrange cardiology assessment with continuous ECG (Holter) monitoring and echocardiography to evaluate for HLA-B27-associated cardiac involvement, including progression of conduction disease', true, 'Correct. HLA-B27-associated spondyloarthropathies (including reactive arthritis and ankylosing spondylitis) carry a recognised, if uncommon, risk of cardiac involvement, including aortic root disease/aortic regurgitation and conduction abnormalities (ranging from first-degree AV block to complete heart block). New conduction abnormality with symptoms (palpitations, pre-syncope) warrants prompt cardiology assessment with ambulatory ECG monitoring and echocardiography, as first-degree block can progress to higher-grade, potentially dangerous block, and needs surveillance and specialist input.', 2),
('df000000-0000-0000-0000-000000000039', 'C', 'Start empirical amiodarone for suspected arrhythmia without further cardiac investigation', false, 'Ruled out because antiarrhythmic therapy should not be started empirically without first characterising the rhythm/conduction abnormality through appropriate monitoring and structural cardiac assessment (echocardiography); this jumps to treatment without diagnostic clarification.', 3),
('df000000-0000-0000-0000-000000000039', 'D', 'Attribute the symptoms to anxiety related to his rheumatological diagnosis and provide reassurance', false, 'Ruled out because a new objective ECG conduction abnormality (change from a previously normal ECG) with correlating symptoms should not be dismissed as anxiety; it requires appropriate cardiac evaluation given the known association between HLA-B27-related spondyloarthropathy and conduction disease.', 4),
('df000000-0000-0000-0000-000000000039', 'E', 'Increase NSAID dose for joint symptoms, as this is unrelated to his rheumatological condition', false, 'Ruled out because this ECG finding is directly relevant to his HLA-B27-associated disease (a recognised extra-articular cardiac manifestation) and requires specific cardiac evaluation, not simply escalation of joint-directed NSAID therapy while disregarding the cardiac finding.', 5),
('df000000-0000-0000-0000-000000000040', 'A', 'Switch to a different anti-TNF agent (or an agent with a different mechanism of action, e.g. an IL-17 inhibitor) rather than increasing the infliximab dose or frequency', true, 'Correct. Undetectable drug trough levels with strongly positive anti-drug antibodies indicate immunogenicity-driven secondary loss of response — the antibodies are neutralising the drug and accelerating its clearance, so simply increasing the infliximab dose or frequency is unlikely to restore efficacy. The appropriate strategy is to switch to a different anti-TNF agent (which may not share the same immunogenicity) or to an agent with a different mechanism of action (e.g. IL-17 inhibition), rather than escalating a drug that can no longer reach effective levels.', 1),
('df000000-0000-0000-0000-000000000040', 'B', 'Increase the infliximab dose and/or shorten the infusion interval to overcome the loss of response', false, 'Ruled out because the loss of response here is driven by anti-drug antibodies neutralising and accelerating clearance of infliximab (reflected by undetectable trough levels); simply increasing dose or frequency in the presence of high-titre neutralising antibodies is unlikely to be effective and does not address the underlying immunogenicity.', 2),
('df000000-0000-0000-0000-000000000040', 'C', 'Add methotrexate to the existing infliximab regimen without switching biologic', false, 'Ruled out because although concomitant methotrexate can reduce immunogenicity when co-prescribed from the outset with anti-TNF therapy, once high-titre neutralising antibodies with undetectable drug levels have already developed, adding methotrexate at this stage is unlikely to reverse established secondary loss of response; switching agent is the more appropriate next step.', 3),
('df000000-0000-0000-0000-000000000040', 'D', 'Assume this represents a primary flare of axial disease unrelated to drug pharmacokinetics and increase background NSAID therapy only', false, 'Ruled out because the drug level and anti-drug antibody results specifically identify an immunogenicity-driven mechanism (secondary loss of response) for the clinical worsening, rather than a coincidental unrelated flare; this should guide the treatment strategy (biologic switch) rather than simply escalating NSAID therapy.', 4),
('df000000-0000-0000-0000-000000000040', 'E', 'Stop biologic therapy altogether and manage with NSAIDs and physiotherapy alone', false, 'Ruled out because this patient has demonstrated a clear need for biologic therapy to control her axial spondyloarthritis (prior 2-year remission on infliximab); the appropriate response to secondary loss of response due to immunogenicity is to switch to a different biologic, not to abandon biologic therapy altogether.', 5),
('df000000-0000-0000-0000-000000000041', 'A', 'Await temporal artery biopsy results before starting corticosteroids, to avoid an unnecessary treatment course', false, 'Ruled out because delaying corticosteroid treatment pending biopsy risks permanent, irreversible visual loss in giant cell arteritis; treatment must be started immediately based on clinical suspicion, with biopsy performed afterwards (still informative within about 2 weeks of starting steroids).', 1),
('df000000-0000-0000-0000-000000000041', 'B', 'Start immediate high-dose corticosteroids (e.g. intravenous methylprednisolone or high-dose oral prednisolone) without waiting for temporal artery biopsy, and arrange biopsy promptly thereafter', true, 'Correct. This presentation is classic giant cell arteritis with visual symptoms (amaurosis fugax), which represents an ophthalmological emergency due to the risk of irreversible visual loss from anterior ischaemic optic neuropathy. High-dose corticosteroids must be started immediately on clinical suspicion, without waiting for temporal artery biopsy (which remains useful diagnostically for up to around 2 weeks after starting steroids, as glucocorticoid-induced changes take time to develop) or imaging confirmation, given the urgency of preventing permanent visual loss.', 2),
('df000000-0000-0000-0000-000000000041', 'C', 'Start a low dose of oral prednisolone (e.g. 15mg daily) and increase gradually based on symptom response', false, 'Ruled out because GCA with visual symptoms requires immediate high-dose corticosteroid treatment (often intravenous methylprednisolone or high-dose oral prednisolone, substantially higher than 15mg) to rapidly suppress vasculitic inflammation and protect against further visual loss; a low, gradually titrated dose is inadequate for this emergency presentation.', 3),
('df000000-0000-0000-0000-000000000041', 'D', 'Arrange urgent CT angiography of the aorta as the priority investigation before any treatment decision', false, 'Ruled out because although imaging has a role in assessing large-vessel involvement in GCA, it is not the priority in a patient with acute visual symptoms; immediate high-dose corticosteroid treatment takes priority over any imaging investigation in this emergency.', 4),
('df000000-0000-0000-0000-000000000041', 'E', 'Refer for urgent ophthalmology assessment only, deferring systemic corticosteroid treatment until vision specialist review is complete', false, 'Ruled out because although ophthalmology input is valuable, corticosteroid treatment for suspected GCA with visual symptoms should not be delayed pending specialist review; treatment is started immediately on clinical suspicion by whichever team first identifies the presentation.', 5),
('df000000-0000-0000-0000-000000000042', 'A', 'Oral corticosteroids alone at a moderate dose, escalating only if there is no improvement after several weeks', false, 'Ruled out because corticosteroid monotherapy is inadequate for severe ANCA-associated vasculitis with organ-threatening (pulmonary-renal) involvement; induction requires combination therapy with a second immunosuppressive agent (rituximab or cyclophosphamide) started promptly, not delayed escalation.', 1),
('df000000-0000-0000-0000-000000000042', 'B', 'Methotrexate combined with low-dose corticosteroids', false, 'Ruled out because methotrexate is used for maintenance therapy or for non-severe, non-organ-threatening ANCA-associated vasculitis; it is not appropriate induction therapy for severe disease with pulmonary-renal syndrome and rapidly progressive glomerulonephritis.', 2),
('df000000-0000-0000-0000-000000000042', 'C', 'High-dose corticosteroids combined with either rituximab or cyclophosphamide, with consideration of plasma exchange given the severity of renal and pulmonary involvement', true, 'Correct. This presentation (diffuse alveolar haemorrhage and rapidly progressive glomerulonephritis with high-titre cANCA/PR3) represents severe ANCA-associated vasculitis (granulomatosis with polyangiitis) with pulmonary-renal syndrome, a life- and organ-threatening presentation. Induction requires high-dose corticosteroids combined with either rituximab or cyclophosphamide (both established and broadly equivalent induction agents per the RAVE and RITUXVAS trial evidence), with plasma exchange considered given the severity of renal involvement and/or diffuse alveolar haemorrhage, per the PEXIVAS trial and subsequent practice.', 3),
('df000000-0000-0000-0000-000000000042', 'D', 'Immediate haemodialysis with no additional immunosuppressive therapy', false, 'Ruled out because although renal replacement therapy may be required to support the patient depending on the degree of renal failure, it does not address the underlying vasculitic process; immunosuppressive induction therapy is essential to halt ongoing organ damage and is not optional here.', 4),
('df000000-0000-0000-0000-000000000042', 'E', 'Hydroxychloroquine and NSAIDs for symptomatic control', false, 'Ruled out because these agents have no meaningful role in treating severe ANCA-associated vasculitis with organ-threatening disease; this represents a medical emergency requiring urgent potent immunosuppressive induction therapy.', 5),
('df000000-0000-0000-0000-000000000043', 'A', 'Continue high-dose corticosteroids alone for a further prolonged course, without adding any additional agent', false, 'Ruled out because this patient already has partial response with problematic steroid toxicity after 8 weeks; continuing corticosteroid monotherapy without a steroid-sparing agent risks ongoing disease activity (with permanent nerve damage) and worsening steroid-related complications.', 1),
('df000000-0000-0000-0000-000000000043', 'B', 'Switch to standard-dose inhaled corticosteroids only, given his background diagnosis of asthma', false, 'Ruled out because this represents systemic vasculitis with major organ involvement (mononeuritis multiplex), not simply poorly controlled asthma; inhaled corticosteroids alone are entirely inadequate for this systemic disease process.', 2),
('df000000-0000-0000-0000-000000000043', 'C', 'Start allopurinol to reduce eosinophil count', false, 'Ruled out because allopurinol is a xanthine oxidase inhibitor used to lower urate in gout; it has no role in reducing eosinophilia or treating EGPA.', 3),
('df000000-0000-0000-0000-000000000043', 'D', 'Refer for lung transplantation given his asthma history', false, 'Ruled out because there is no indication for lung transplantation in this presentation; his disease is systemic vasculitis with reasonably controlled asthma, requiring targeted immunosuppressive/biologic therapy, not transplantation.', 4),
('df000000-0000-0000-0000-000000000043', 'E', 'Add mepolizumab (anti-IL-5 monoclonal antibody) as steroid-sparing therapy', true, $x$Correct. This presentation (adult-onset asthma, marked eosinophilia, sinusitis, and mononeuritis multiplex with MPO-ANCA positivity) is classic eosinophilic granulomatosis with polyangiitis (EGPA, formerly Churg-Strauss syndrome). In patients with relapsing or refractory disease, or an inability to taper corticosteroids without relapse/toxicity, mepolizumab is an established, licensed steroid-sparing therapy that targets the eosinophilic pathway central to this disease's pathogenesis.$x$, 5),
('df000000-0000-0000-0000-000000000044', 'A', 'Combine clinical assessment with vascular imaging (e.g. MR/CT angiography or PET-CT) to assess disease activity, as inflammatory markers correlate poorly with true disease activity in this condition', true, 'Correct. This presentation (young woman, large-vessel involvement with subclavian/aortic arch stenosis, pulse and blood pressure discrepancy) is classic Takayasu arteritis. A key management challenge is that ESR/CRP correlate poorly with true disease activity in Takayasu arteritis, and a substantial proportion of patients with ongoing vascular inflammation and progression have normal or only mildly elevated inflammatory markers; treatment decisions should therefore integrate clinical assessment with vascular imaging (repeat angiography or PET-CT) rather than relying on inflammatory markers alone.', 1),
('df000000-0000-0000-0000-000000000044', 'B', 'Rely solely on serial ESR and CRP measurements to guide escalation or tapering of immunosuppression', false, 'Ruled out because inflammatory markers are a recognised unreliable indicator of disease activity in Takayasu arteritis; relying on them alone risks under- or over-treating patients whose true vascular disease activity is not reflected by ESR/CRP.', 2),
('df000000-0000-0000-0000-000000000044', 'C', 'Base all treatment decisions solely on the degree of claudication symptoms reported by the patient', false, 'Ruled out because symptoms such as claudication may reflect fixed vascular stenosis/damage rather than ongoing active inflammation, and can persist or be absent independent of current disease activity; imaging and comprehensive clinical assessment are needed rather than symptoms alone.', 3),
('df000000-0000-0000-0000-000000000044', 'D', 'Perform temporal artery biopsy to confirm the diagnosis and guide treatment', false, 'Ruled out because temporal artery biopsy is relevant to giant cell arteritis (typically affecting older patients and cranial vessels), not Takayasu arteritis, which characteristically affects the aorta and its major branches in younger patients; it would not be an appropriate or informative test here.', 4),
('df000000-0000-0000-0000-000000000044', 'E', 'Defer any treatment decisions until tissue biopsy of the affected subclavian artery is obtained', false, 'Ruled out because biopsy of large deep vessels such as the subclavian artery or aorta is generally impractical and unnecessary for diagnosis or monitoring; Takayasu arteritis is diagnosed and monitored using a combination of clinical features and vascular imaging, not tissue biopsy.', 5),
('df000000-0000-0000-0000-000000000045', 'A', 'Long-term cyclophosphamide and high-dose corticosteroids as for idiopathic polyarteritis nodosa, without addressing the hepatitis B infection', false, 'Ruled out because in hepatitis B-associated PAN, prolonged potent immunosuppression (as used in idiopathic PAN) without antiviral treatment risks exacerbating viral replication and worsening liver disease; the specific evidence-based approach for HBV-associated PAN prioritises antiviral therapy alongside a short course of corticosteroids/plasma exchange, not prolonged immunosuppression alone.', 1),
('df000000-0000-0000-0000-000000000045', 'B', 'Interferon-alpha monotherapy without corticosteroids or antiviral nucleos(t)ide analogues', false, 'Ruled out because although interferon has historically been used in some HBV-associated vasculitis regimens, contemporary practice favours nucleos(t)ide analogue antiviral therapy combined with corticosteroids (and plasma exchange for severe disease) rather than interferon monotherapy alone; the acute inflammatory manifestations also require corticosteroid cover.', 2),
('df000000-0000-0000-0000-000000000045', 'C', 'Liver transplantation as definitive treatment for the vasculitis', false, 'Ruled out because liver transplantation addresses end-stage liver disease, not the vasculitis itself, and is not an appropriate treatment for hepatitis B-associated PAN at this stage; antiviral therapy and appropriately limited immunosuppression are the correct approach.', 3),
('df000000-0000-0000-0000-000000000045', 'D', 'Antiviral therapy targeting hepatitis B, combined with a short course of corticosteroids and plasma exchange for severe manifestations, avoiding long-term potent immunosuppression', true, 'Correct. This presentation (medium-vessel vasculitis with microaneurysms, mononeuritis multiplex, livedo reticularis, ANCA-negative, and active hepatitis B replication) is classic hepatitis B-associated polyarteritis nodosa. Because ongoing viral replication drives the vasculitis, management centres on antiviral therapy to control hepatitis B, combined with a short course of corticosteroids (often with plasma exchange for severe disease) to control the acute inflammatory manifestations, while avoiding prolonged potent immunosuppression, which risks promoting further viral replication and worsening hepatic disease.', 4),
('df000000-0000-0000-0000-000000000045', 'E', 'Rituximab as first-line induction therapy, as used in ANCA-associated vasculitis', false, $x$Ruled out because rituximab's evidence base and licensing is for ANCA-associated vasculitis, and this patient is ANCA-negative with a distinct, HBV-driven medium-vessel vasculitis (PAN); the recommended approach centres on antiviral therapy, not B-cell depletion.$x$, 5),
('df000000-0000-0000-0000-000000000046', 'A', 'Colchicine alone, as used for isolated mucocutaneous ulceration', false, $x$Ruled out because colchicine alone is inadequate for posterior uveitis with retinal vasculitis, which is a sight-threatening, major-organ manifestation requiring systemic immunosuppression; colchicine's role is principally for mucocutaneous and joint symptoms.$x$, 1),
('df000000-0000-0000-0000-000000000046', 'B', 'Systemic immunosuppression with azathioprine (or an anti-TNF biologic/interferon-alpha in refractory or severe cases), in addition to colchicine for mucocutaneous symptoms', true, $x$Correct. Posterior uveitis and retinal vasculitis in Behcet's disease carry a significant risk of permanent visual loss and represent a major organ-threatening manifestation requiring systemic immunosuppression (typically azathioprine, escalating to anti-TNF biologic therapy or interferon-alpha for severe or refractory eye disease), which differs from the milder colchicine-based approach used for isolated mucocutaneous (oral/genital ulcer) disease.$x$, 2),
('df000000-0000-0000-0000-000000000046', 'C', 'Topical corticosteroid eye drops alone, without any systemic therapy', false, 'Ruled out because posterior uveitis with retinal vasculitis is a serious, sight-threatening manifestation that responds poorly to topical treatment alone (which penetrates poorly to the posterior segment); systemic immunosuppression is required to prevent progressive visual loss.', 3),
('df000000-0000-0000-0000-000000000046', 'D', $x$Observation only, as Behcet's-associated eye disease typically resolves spontaneously$x$, false, $x$Ruled out because posterior uveitis/retinal vasculitis in Behcet's disease does not reliably resolve spontaneously and carries a substantial risk of progressive, irreversible visual impairment if untreated; prompt systemic immunosuppression is required.$x$, 4),
('df000000-0000-0000-0000-000000000046', 'E', 'Thalidomide monotherapy as first-line treatment for the eye disease', false, $x$Ruled out because thalidomide's main use in Behcet's disease is for severe mucocutaneous ulceration refractory to other treatments, not as first-line therapy for posterior uveitis, where azathioprine or biologic therapy is the established approach.$x$, 5),
('df000000-0000-0000-0000-000000000047', 'A', 'Intravenous immunoglobulin as an alternative to plasma exchange', false, 'Ruled out because IVIG is not an established standard adjunct therapy for severe renal involvement in ANCA-associated vasculitis; plasma exchange has a specific evidence base and role in this context, which IVIG does not replicate.', 1),
('df000000-0000-0000-0000-000000000047', 'B', 'Splenectomy to reduce autoantibody production', false, 'Ruled out because splenectomy has no established role in the management of ANCA-associated vasculitis; this is not a recognised or appropriate intervention for severe renal involvement in this condition.', 2),
('df000000-0000-0000-0000-000000000047', 'C', 'Plasma exchange', true, 'Correct. In ANCA-associated vasculitis with severe renal involvement (very high creatinine, a large proportion of crescents on biopsy, indicating rapidly progressive glomerulonephritis), plasma exchange is considered as an adjunct to standard induction immunosuppression, based on evidence (including the PEXIVAS trial) suggesting benefit in preventing progression to end-stage renal disease in patients presenting with severe renal impairment, even though the overall PEXIVAS results did not show a mortality or composite outcome benefit across the whole study population; its use is guided by disease severity and individualised risk-benefit assessment.', 3),
('df000000-0000-0000-0000-000000000047', 'D', 'Renal artery embolisation to reduce ongoing glomerular inflammation', false, 'Ruled out because renal artery embolisation is not a treatment for glomerulonephritis; it has no role in ANCA-associated vasculitis management and would not address the underlying immune-mediated glomerular injury.', 4),
('df000000-0000-0000-0000-000000000047', 'E', 'Discontinuing corticosteroids in favour of cyclophosphamide alone, to reduce cumulative steroid exposure', false, 'Ruled out because corticosteroids remain a core component of induction therapy in ANCA-associated vasculitis alongside cyclophosphamide or rituximab; they should not be discontinued, though steroid-sparing regimens (reduced-dose steroid protocols) have been studied and can be considered as part of an overall strategy to reduce cumulative toxicity, distinct from stopping steroids altogether.', 5),
('df000000-0000-0000-0000-000000000048', 'A', 'Increase the corticosteroid dose permanently to a level above the relapse threshold, accepting the toxicity', false, 'Ruled out because this approach fails to address the significant and worsening cumulative corticosteroid toxicity already present (osteoporosis, diabetes, cataracts); a steroid-sparing strategy is preferred over indefinitely maintaining higher glucocorticoid doses.', 1),
('df000000-0000-0000-0000-000000000048', 'B', 'Stop corticosteroids altogether and switch to methotrexate monotherapy', false, 'Ruled out because methotrexate has more modest steroid-sparing efficacy in GCA compared with tocilizumab and abrupt cessation of corticosteroids in active/relapsing disease risks a significant flare; the evidence-based approach is to add tocilizumab to facilitate a more gradual, successful taper, not to substitute methotrexate alone and stop steroids abruptly.', 2),
('df000000-0000-0000-0000-000000000048', 'C', 'Perform repeat temporal artery biopsy to confirm ongoing disease activity before considering any treatment change', false, 'Ruled out because temporal artery biopsy is a diagnostic tool used at initial presentation; it is not used to monitor disease activity or guide treatment escalation decisions in established, relapsing GCA, where clinical and biochemical relapse (as described) is sufficient to prompt treatment adjustment.', 3),
('df000000-0000-0000-0000-000000000048', 'D', 'Refer for temporal artery bypass surgery to prevent further relapses', false, 'Ruled out because temporal artery bypass surgery has no established role in the management of giant cell arteritis, which is a medical (immunosuppressive), not surgical, condition; relapses are managed with pharmacological steroid-sparing therapy.', 4),
('df000000-0000-0000-0000-000000000048', 'E', 'Add tocilizumab as a steroid-sparing agent to facilitate corticosteroid tapering', true, 'Correct. Tocilizumab (an IL-6 receptor antagonist) is licensed and evidence-based (GiACTA trial) for relapsing giant cell arteritis, allowing more effective corticosteroid tapering and reducing relapse rates. In a patient with relapsing disease and significant cumulative steroid toxicity (osteoporosis, diabetes, cataracts), adding tocilizumab as a steroid-sparing agent is the appropriate next step rather than continuing to rely on higher, sustained corticosteroid doses.', 5),
('df000000-0000-0000-0000-000000000049', 'A', 'Long-term high-dose corticosteroids and cyclophosphamide, without antiviral therapy', false, 'Ruled out because treating hepatitis C-associated cryoglobulinaemic vasculitis with potent immunosuppression alone, without addressing the underlying viral infection driving the disease, is not the evidence-based first-line approach and cyclophosphamide is now largely avoided in this context given the availability of effective, better-tolerated options.', 1),
('df000000-0000-0000-0000-000000000049', 'B', 'Interferon-based antiviral therapy without direct-acting antivirals or immunosuppression', false, 'Ruled out because interferon-based regimens have largely been superseded by direct-acting antivirals, which are more effective and better tolerated for treating hepatitis C; in the presence of severe organ-threatening vasculitis, immunosuppression alongside antiviral therapy is also required, not antiviral therapy alone in this severity of presentation.', 2),
('df000000-0000-0000-0000-000000000049', 'C', 'Plasma exchange as monotherapy, without any antiviral or immunosuppressive therapy', false, 'Ruled out because although plasma exchange can be used as an adjunct in severe cryoglobulinaemic vasculitis, it does not address the underlying driver (hepatitis C infection) and is not used as sole therapy without antiviral treatment and, where indicated, targeted immunosuppression.', 3),
('df000000-0000-0000-0000-000000000049', 'D', 'Direct-acting antiviral therapy targeting hepatitis C as primary treatment, with immunosuppression (e.g. rituximab) reserved for severe or organ-threatening manifestations', true, $x$Correct. Hepatitis C-associated cryoglobulinaemic vasculitis is driven by ongoing viral infection stimulating cryoglobulin (typically type II, mixed) production; treatment of the underlying hepatitis C with direct-acting antivirals is now first-line therapy and can resolve the vasculitis in many patients. Immunosuppression, particularly rituximab (given its efficacy in cryoglobulinaemic vasculitis and relatively favourable safety profile with respect to HCV replication compared with broader immunosuppression), is reserved for severe, organ-threatening manifestations (e.g. this patient's significant renal involvement) alongside antiviral therapy, rather than as an alternative to treating the virus.$x$, 4),
('df000000-0000-0000-0000-000000000049', 'E', 'Liver transplantation as first-line treatment for the vasculitis', false, 'Ruled out because this patient does not have decompensated liver disease requiring transplantation; the appropriate first-line approach is antiviral therapy for hepatitis C (with immunosuppression for severe vasculitis), not transplantation.', 5),
('df000000-0000-0000-0000-000000000050', 'A', 'Immunosuppressive treatment (corticosteroids, with consideration of an additional agent such as mycophenolate or cyclophosphamide) given significant nephritis with crescents, recognising that adults with IgA vasculitis have a worse renal prognosis than children', true, 'Correct. IgA vasculitis (Henoch-Schonlein purpura) in adults carries a significantly worse renal prognosis than in children, with a higher risk of progression to chronic kidney disease and end-stage renal failure. Significant nephritis (proteinuria, renal impairment, crescents on biopsy) in an adult with IgA vasculitis warrants active immunosuppressive treatment (corticosteroids, often combined with an additional agent such as mycophenolate mofetil or cyclophosphamide for more severe/crescentic disease), rather than the more conservative, often self-limiting approach sometimes appropriate in mild paediatric cases.', 1),
('df000000-0000-0000-0000-000000000050', 'B', 'Supportive care alone with analgesia, expecting spontaneous resolution as typically occurs in children', false, 'Ruled out because although IgA vasculitis is often self-limiting in children, adults have a substantially worse renal prognosis, and significant nephritis with crescents (as seen here) requires active immunosuppressive treatment rather than supportive care alone, which risks progression to chronic kidney disease.', 2),
('df000000-0000-0000-0000-000000000050', 'C', 'Long-term prophylactic antibiotics to prevent recurrent vasculitis episodes', false, 'Ruled out because there is no established role for prophylactic antibiotics in the management of IgA vasculitis; this is an immune-mediated small-vessel vasculitis, not an infectious process requiring antimicrobial prophylaxis.', 3),
('df000000-0000-0000-0000-000000000050', 'D', 'Renal biopsy is unnecessary in IgA vasculitis and should not have been performed', false, 'Ruled out because renal biopsy is important in adults with IgA vasculitis and significant renal involvement, as it provides prognostic information (e.g. presence and extent of crescents) that guides the decision to use immunosuppression, particularly given the worse renal prognosis in adults compared with children.', 4),
('df000000-0000-0000-0000-000000000050', 'E', 'Dapsone monotherapy as the treatment of choice for the renal involvement', false, 'Ruled out because dapsone has a role in some cases of predominantly cutaneous IgA vasculitis, but is not appropriate or sufficient treatment for significant IgA nephritis with crescents, which requires immunosuppressive therapy directed at the renal disease.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('df000000-0000-0000-0000-000000000001', 'In class III/IV lupus nephritis, mycophenolate mofetil and cyclophosphamide have comparable efficacy for induction; MMF is preferred in women of reproductive age because it avoids the gonadotoxic risk of cyclophosphamide.', 1),
('df000000-0000-0000-0000-000000000001', 'Active nephritic sediment (red cell casts), rising creatinine, heavy proteinuria, low complement and high anti-dsDNA together indicate active proliferative nephritis requiring prompt induction immunosuppression, not escalation of antimalarial therapy alone.', 2),
('df000000-0000-0000-0000-000000000001', 'Belimumab and rituximab are used as adjuncts to, not replacements for, standard induction immunosuppression in lupus nephritis.', 3),
('df000000-0000-0000-0000-000000000002', 'Triple antibody positivity (lupus anticoagulant, anticardiolipin, and anti-beta2-glycoprotein I) identifies the highest-risk APS subgroup for recurrent and arterial thrombosis.', 1),
('df000000-0000-0000-0000-000000000002', 'Direct oral anticoagulants are inferior to vitamin K antagonists for secondary thromboprophylaxis in APS, particularly in triple-positive and arterial-event patients, and should generally be avoided.', 2),
('df000000-0000-0000-0000-000000000002', 'Recurrent arterial thrombosis on standard-intensity warfarin in APS warrants escalation to a high-intensity INR target (3.0-4.0) rather than a change in anticoagulant class.', 3),
('df000000-0000-0000-0000-000000000003', 'Scleroderma renal crisis typically occurs early in diffuse cutaneous systemic sclerosis, particularly in anti-RNA polymerase III antibody-positive patients, and presents with abrupt severe hypertension, AKI, and microangiopathic haemolysis/thrombocytopenia.', 1),
('df000000-0000-0000-0000-000000000003', 'ACE inhibitors must be started and up-titrated promptly even when renal function is worsening, as they are the only therapy proven to improve outcomes; withholding them due to rising creatinine is a key avoidable error.', 2),
('df000000-0000-0000-0000-000000000003', 'High-dose corticosteroids are a recognised risk factor for precipitating scleroderma renal crisis and should be used cautiously, if at all, in early diffuse systemic sclerosis.', 3),
('df000000-0000-0000-0000-000000000004', 'In systemic sclerosis, a disproportionate reduction in DLCO relative to FVC (in the absence of significant ILD) is a key pattern suggesting pulmonary arterial hypertension.', 1),
('df000000-0000-0000-0000-000000000004', 'Right heart catheterisation is required to confirm the diagnosis of PAH and guide the decision to start PAH-specific therapy; non-invasive tests (echo, NT-proBNP, PFTs) are used for screening and risk stratification, not definitive diagnosis.', 2),
('df000000-0000-0000-0000-000000000004', 'Annual screening for PAH is recommended in systemic sclerosis, particularly limited cutaneous disease, given its major contribution to mortality.', 3),
('df000000-0000-0000-0000-000000000005', 'Anti-MDA5 antibody-positive dermatomyositis is associated with a hypomyopathic phenotype and a high risk of rapidly progressive interstitial lung disease with substantial short-term mortality.', 1),
('df000000-0000-0000-0000-000000000005', 'Creatine kinase levels correlate poorly with disease severity in anti-MDA5 disease; skin and lung findings, not CK, guide urgency of treatment.', 2),
('df000000-0000-0000-0000-000000000005', 'Early aggressive combination immunosuppression, rather than stepwise escalation, improves survival in anti-MDA5-associated rapidly progressive ILD.', 3),
('df000000-0000-0000-0000-000000000006', $x$Primary Sjogren's syndrome carries a significantly increased risk of B-cell (typically MALT) lymphoma compared with the general population.$x$, 1),
('df000000-0000-0000-0000-000000000006', $x$Persistent parotid/salivary gland enlargement, monoclonal gammopathy, cryoglobulinaemia, and low C4 are recognised predictors of lymphoma development in Sjogren's syndrome and warrant biopsy.$x$, 2),
('df000000-0000-0000-0000-000000000006', 'Tissue diagnosis should precede immunosuppressive treatment decisions when lymphoma is a realistic differential, as management diverges significantly from that of benign glandular disease.', 3),
('df000000-0000-0000-0000-000000000007', 'Hydroxychloroquine retinopathy can be detected on screening (OCT, visual fields, fundus autofluorescence) before the patient becomes symptomatic, which is why annual screening after 5 years of use is recommended.', 1),
('df000000-0000-0000-0000-000000000007', 'Once retinopathy is identified, hydroxychloroquine should be stopped, as retinal damage is not reversible and can progress even after cessation.', 2),
('df000000-0000-0000-0000-000000000007', 'Chloroquine carries a higher, not lower, risk of retinal toxicity compared with hydroxychloroquine and is not an appropriate substitute.', 3),
('df000000-0000-0000-0000-000000000008', $x$Mixed connective tissue disease is characterised by anti-U1-RNP antibodies together with overlapping features of SLE, systemic sclerosis and myositis (Raynaud's, puffy hands, arthritis, myositis).$x$, 1),
('df000000-0000-0000-0000-000000000008', 'Pulmonary arterial hypertension is a recognised and potentially insidious complication of MCTD and a major contributor to mortality, warranting periodic screening even when asymptomatic.', 2),
('df000000-0000-0000-0000-000000000008', 'Scleroderma renal crisis is specific to diffuse cutaneous systemic sclerosis (particularly with anti-RNA polymerase III antibodies), not MCTD.', 3),
('df000000-0000-0000-0000-000000000009', $x$Antisynthetase syndrome (anti-Jo-1 and related antibodies) presents with the triad of myositis, mechanic's hands, and inflammatory arthritis, with interstitial lung disease as a major determinant of prognosis.$x$, 1),
('df000000-0000-0000-0000-000000000009', 'ILD in antisynthetase syndrome can progress independently of myositis activity and requires its own surveillance and targeted immunosuppression, not treatment of muscle disease alone.', 2),
('df000000-0000-0000-0000-000000000009', 'Corticosteroids alone are often insufficient; a steroid-sparing immunosuppressant is typically added given the risk of relapse and lung progression.', 3),
('df000000-0000-0000-0000-000000000010', 'Mycophenolate mofetil and methotrexate are both teratogenic and must be stopped well before conception; azathioprine is the preferred substitute for maintaining immunosuppression through pregnancy.', 1),
('df000000-0000-0000-0000-000000000010', 'Hydroxychloroquine should be continued throughout pregnancy in SLE, as it reduces flare risk without fetal harm.', 2),
('df000000-0000-0000-0000-000000000010', 'Pre-conception planning in lupus nephritis aims to maintain disease quiescence with pregnancy-compatible agents rather than simply withdrawing immunosuppression, which risks flare.', 3),
('df000000-0000-0000-0000-000000000011', 'NSAIDs should generally be avoided in patients with significant CKD due to nephrotoxicity risk; corticosteroids or dose-adjusted colchicine are safer alternatives for acute gout in this context.', 1),
('df000000-0000-0000-0000-000000000011', 'Colchicine requires substantial dose reduction (or avoidance) in advanced renal impairment because of the risk of accumulation and serious toxicity.', 2),
('df000000-0000-0000-0000-000000000011', 'Urate-lowering therapy does not treat acute flares and should not be relied upon (or newly started at treatment dose without cover) as acute management.', 3),
('df000000-0000-0000-0000-000000000012', 'Allopurinol is often underdosed at 300mg; treat-to-target dose escalation (with monitoring) achieves target urate in most patients and should be attempted before switching agents.', 1),
('df000000-0000-0000-0000-000000000012', 'Febuxostat carries an increased cardiovascular mortality risk compared with allopurinol in patients with pre-existing cardiovascular disease, and should be used cautiously in this population.', 2),
('df000000-0000-0000-0000-000000000012', 'Thiazide diuretics raise serum urate and are a recognised precipitant of gout, not a treatment for hyperuricaemia.', 3),
('df000000-0000-0000-0000-000000000013', 'Urate-lowering therapy can and should be started during an acute gout flare provided the flare is adequately treated and prophylactic anti-inflammatory cover is given, rather than delaying until the attack has settled.', 1),
('df000000-0000-0000-0000-000000000013', 'Allopurinol remains first-line urate-lowering therapy for most patients; febuxostat is generally second-line given its cardiovascular safety profile.', 2),
('df000000-0000-0000-0000-000000000013', 'Recurrent flares and significantly elevated serum urate are indications to initiate definitive urate-lowering therapy rather than relying on prophylaxis alone.', 3),
('df000000-0000-0000-0000-000000000014', 'Identification of crystals in synovial fluid does not exclude coexisting septic arthritis; the two can occur together, and clinical suspicion (fever, marked leucocytosis, very high synovial WCC) should still prompt culture and empirical antibiotic cover.', 1),
('df000000-0000-0000-0000-000000000014', 'Intra-articular corticosteroid injection should be avoided until septic arthritis has been reasonably excluded, to avoid seeding or worsening joint infection.', 2),
('df000000-0000-0000-0000-000000000014', 'Empirical antibiotics should be started after appropriate cultures are obtained rather than delayed pending results, given the risk of rapid joint destruction with untreated septic arthritis.', 3),
('df000000-0000-0000-0000-000000000015', 'HLA-B*5801 is strongly associated with severe allopurinol hypersensitivity syndrome (including SJS/TEN) and is significantly more prevalent in Han Chinese, Thai, and Korean populations.', 1),
('df000000-0000-0000-0000-000000000015', 'Guidelines recommend HLA-B*5801 screening before starting allopurinol in high-risk ethnic groups; a positive result should prompt use of an alternative urate-lowering agent.', 2),
('df000000-0000-0000-0000-000000000015', 'Dose titration and antihistamine prophylaxis do not mitigate the immunogenetic risk of allopurinol hypersensitivity syndrome.', 3),
('df000000-0000-0000-0000-000000000016', 'Pegloticase generates hydrogen peroxide as it converts uric acid to allantoin, which can cause severe haemolysis and methaemoglobinaemia in G6PD-deficient patients; G6PD screening is mandatory before treatment.', 1),
('df000000-0000-0000-0000-000000000016', 'Pegloticase is reserved for refractory chronic tophaceous gout that has failed appropriately dosed xanthine oxidase inhibitor therapy.', 2),
('df000000-0000-0000-0000-000000000016', 'Different urate-lowering agents carry distinct, specific pre-treatment safety screening requirements (HLA-B*5801 for allopurinol; G6PD status for pegloticase).', 3),
('df000000-0000-0000-0000-000000000017', 'Loop and thiazide diuretics raise serum urate and are a common precipitant of gout, but should not be withdrawn if clinically required for heart failure management; hyperuricaemia should instead be treated directly.', 1),
('df000000-0000-0000-0000-000000000017', 'Diuretic-induced hyperuricaemia responds to standard urate-lowering therapy (e.g. allopurinol) in the same way as other causes of gout.', 2),
('df000000-0000-0000-0000-000000000017', 'Losartan has a mild uricosuric effect and can be a useful adjunct antihypertensive in gout patients, but is not a substitute for loop diuretic-based volume management in heart failure.', 3),
('df000000-0000-0000-0000-000000000018', 'Initiating or escalating urate-lowering therapy transiently increases flare risk due to urate mobilisation; prophylactic low-dose colchicine or NSAID is recommended for the first 3-6 months.', 1),
('df000000-0000-0000-0000-000000000018', 'Flares occurring during ULT titration with adequate prophylaxis do not indicate treatment failure and should not prompt discontinuation of urate-lowering therapy.', 2),
('df000000-0000-0000-0000-000000000018', 'Allopurinol has no direct anti-inflammatory action; its benefit is through reduction of urate synthesis, not flare suppression, which is why separate anti-inflammatory prophylaxis is needed at initiation.', 3),
('df000000-0000-0000-0000-000000000019', 'CPPD presenting at a younger age (typically under 55) or with an unusual pattern should prompt screening for secondary metabolic causes: hyperparathyroidism, haemochromatosis, hypomagnesaemia, and hypophosphatasia.', 1),
('df000000-0000-0000-0000-000000000019', 'Primary hyperparathyroidism is a recognised secondary cause of CPPD; identifying and managing the underlying metabolic abnormality is an important part of overall management.', 2),
('df000000-0000-0000-0000-000000000019', 'Allopurinol is specific to urate-lowering in gout and has no role in calcium pyrophosphate deposition disease.', 3),
('df000000-0000-0000-0000-000000000020', 'A hot, swollen prosthetic joint must be treated as possible prosthetic joint infection until excluded, regardless of a background history of gout or other crystal arthropathy.', 1),
('df000000-0000-0000-0000-000000000020', 'Joint aspiration for culture, Gram stain and crystal analysis should generally precede antibiotic administration (in a stable patient) to preserve diagnostic yield.', 2),
('df000000-0000-0000-0000-000000000020', 'Intra-articular corticosteroid injection is contraindicated when prosthetic joint infection has not yet been excluded.', 3),
('df000000-0000-0000-0000-000000000021', 'Anti-TNF therapy carries a recognised risk of reactivating latent tuberculosis, which can present atypically or disseminate; screening (IGRA and chest radiograph) is mandatory before initiation.', 1),
('df000000-0000-0000-0000-000000000021', 'Latent TB is asymptomatic by definition, so screening cannot be omitted on the basis of a normal clinical assessment.', 2),
('df000000-0000-0000-0000-000000000021', 'If latent TB is identified on screening, treatment is generally required before or concurrent with starting the biologic agent.', 3),
('df000000-0000-0000-0000-000000000022', 'Methotrexate is teratogenic and must be stopped at least 3 months before conception; it is absolutely contraindicated in pregnancy.', 1),
('df000000-0000-0000-0000-000000000022', 'Certolizumab pegol lacks an Fc region and shows minimal to no active placental transfer, making it the preferred anti-TNF agent to continue through pregnancy when ongoing biologic therapy is needed.', 2),
('df000000-0000-0000-0000-000000000022', 'Maintaining disease control through pregnancy with a pregnancy-compatible agent is preferred over stopping all therapy, since uncontrolled RA activity itself carries pregnancy risks.', 3),
('df000000-0000-0000-0000-000000000023', 'Rituximab (anti-CD20) is used therapeutically in B-cell lymphomas and is generally considered a favourable biologic choice for RA patients with a prior history of lymphoma.', 1),
('df000000-0000-0000-0000-000000000023', 'TNF inhibitors have historically been approached with more caution regarding malignancy recurrence risk, although the evidence is not entirely consistent across studies.', 2),
('df000000-0000-0000-0000-000000000023', 'JAK inhibitors carry specific long-term surveillance warnings regarding malignancy, venous thromboembolism, and major adverse cardiovascular events, influencing biologic/targeted therapy sequencing decisions.', 3),
('df000000-0000-0000-0000-000000000024', 'The ORAL Surveillance trial showed increased VTE and major adverse cardiovascular event risk with tofacitinib compared with TNF inhibitors, particularly in patients aged 50+ with additional cardiovascular risk factors; this is now considered a JAK inhibitor class effect.', 1),
('df000000-0000-0000-0000-000000000024', 'JAK inhibitors should generally be avoided in patients with significant pre-existing VTE risk or established cardiovascular disease, in favour of alternative-mechanism biologics.', 2),
('df000000-0000-0000-0000-000000000024', 'TNF inhibitors were associated with a lower risk of VTE/MACE than tofacitinib in the pivotal safety trial, informing sequencing decisions in higher-risk patients.', 3),
('df000000-0000-0000-0000-000000000025', $x$Felty's syndrome (rheumatoid arthritis, splenomegaly, neutropenia) has neutropenia that is closely linked to underlying RA disease activity; methotrexate is first-line and often improves the neutrophil count.$x$, 1),
('df000000-0000-0000-0000-000000000025', 'Splenectomy is reserved for cases refractory to medical management or with recurrent severe infection/bleeding, not used as initial therapy.', 2),
('df000000-0000-0000-0000-000000000025', 'Withdrawing disease-modifying therapy would be expected to worsen, not improve, the neutropenia in this disease-activity-linked cytopenia.', 3),
('df000000-0000-0000-0000-000000000026', $x$Adult-onset Still's disease presents with quotidian high spiking fevers, an evanescent salmon-pink rash, sore throat, arthralgia/arthritis, and markedly elevated ferritin, typically with negative RF/ANA.$x$, 1),
('df000000-0000-0000-0000-000000000026', $x$IL-1 blockade (e.g. anakinra) is highly effective in adult-onset Still's disease refractory to NSAIDs and corticosteroids, reflecting its position within the autoinflammatory disease spectrum.$x$, 2),
('df000000-0000-0000-0000-000000000026', 'Very high ferritin in this clinical context should also raise awareness of the risk of macrophage activation syndrome, a life-threatening complication requiring prompt recognition.', 3),
('df000000-0000-0000-0000-000000000027', 'Rituximab and other B-cell depleting therapies carry a significant risk of hepatitis B reactivation, including in patients with resolved past infection (HBsAg negative, anti-HBc positive).', 1),
('df000000-0000-0000-0000-000000000027', 'Screening with HBsAg and anti-HBc should be performed before starting rituximab, with antiviral prophylaxis or monitoring guided by the results.', 2),
('df000000-0000-0000-0000-000000000027', 'Normal liver function tests do not exclude hepatitis B carriage or past infection and cannot substitute for serological screening before immunosuppression.', 3),
('df000000-0000-0000-0000-000000000028', 'AA amyloidosis complicating long-standing rheumatoid arthritis is driven by chronically elevated serum amyloid A; management focuses on aggressively controlling the underlying inflammatory disease.', 1),
('df000000-0000-0000-0000-000000000028', 'IL-6 pathway blockade (e.g. tocilizumab) is particularly effective at lowering serum amyloid A and has a specific evidence base in AA amyloidosis management.', 2),
('df000000-0000-0000-0000-000000000028', 'AA amyloidosis (secondary, inflammation-driven) must be distinguished from AL amyloidosis (plasma cell dyscrasia-related), as their management differs substantially (anti-inflammatory therapy vs anti-plasma cell chemotherapy).', 3),
('df000000-0000-0000-0000-000000000029', 'Anti-TNF agents are relatively contraindicated in moderate-to-severe (NYHA III-IV) heart failure due to evidence of worsening heart failure and increased mortality in this population.', 1),
('df000000-0000-0000-0000-000000000029', 'Alternative-mechanism biologics such as rituximab and abatacept do not carry this specific heart failure contraindication and are reasonable choices when anti-TNF therapy is avoided for this reason.', 2),
('df000000-0000-0000-0000-000000000029', $x$JAK inhibitors carry their own distinct cardiovascular safety concerns (VTE, MACE) and are not a default 'safe' alternative in significant cardiac disease.$x$, 3),
('df000000-0000-0000-0000-000000000030', 'Methotrexate pneumonitis is an idiosyncratic, potentially life-threatening drug reaction presenting with subacute dyspnoea, dry cough, fever, and bilateral ground-glass changes, overlapping significantly with infection.', 1),
('df000000-0000-0000-0000-000000000030', 'Methotrexate should be stopped immediately when pneumonitis is suspected, while infection (including opportunistic pathogens in an immunosuppressed patient) is actively investigated in parallel.', 2),
('df000000-0000-0000-0000-000000000030', 'High-dose corticosteroids are used when methotrexate pneumonitis is confirmed or remains the leading diagnosis after appropriate investigation.', 3),
('df000000-0000-0000-0000-000000000031', 'Conventional synthetic DMARDs (methotrexate, sulfasalazine) lack proven efficacy for axial disease in ankylosing spondylitis, even though they may help peripheral arthritis.', 1),
('df000000-0000-0000-0000-000000000031', 'Biologic therapy (anti-TNF or IL-17 inhibition) is indicated for active axial spondyloarthritis with inadequate response to an adequate trial of NSAIDs.', 2),
('df000000-0000-0000-0000-000000000031', 'Objective evidence of active inflammation (MRI bone marrow oedema) alongside persistent clinical disease activity (BASDAI) supports the decision to escalate therapy.', 3),
('df000000-0000-0000-0000-000000000032', $x$IL-17 inhibitors are associated with new-onset or exacerbation of inflammatory bowel disease and should generally be avoided in patients with coexisting Crohn's disease or ulcerative colitis.$x$, 1),
('df000000-0000-0000-0000-000000000032', 'Anti-TNF agents and IL-12/23 inhibitors are preferred biologic choices in patients with both psoriatic arthritis (or spondyloarthritis) and inflammatory bowel disease, as they do not carry this specific risk.', 2),
('df000000-0000-0000-0000-000000000032', 'Biologic selection in spondyloarthropathy should account for extra-articular disease associations (IBD, uveitis, psoriasis), not joint disease alone.', 3),
('df000000-0000-0000-0000-000000000033', 'Reactive arthritis is a sterile, immune-mediated arthritis triggered by a preceding genitourinary (commonly chlamydial) or gastrointestinal infection, classically with asymmetric oligoarthritis, conjunctivitis and mucocutaneous lesions.', 1),
('df000000-0000-0000-0000-000000000033', 'Management requires both treatment of the triggering infection (with partner notification/treatment for sexually transmitted causes) and separate symptomatic treatment of the sterile arthritis (NSAIDs, intra-articular steroids).', 2),
('df000000-0000-0000-0000-000000000033', 'Biologic therapy is reserved for chronic/relapsing reactive arthritis refractory to standard measures, not first-line acute management.', 3),
('df000000-0000-0000-0000-000000000034', 'Monoclonal anti-TNF antibodies (adalimumab, infliximab, golimumab) are more effective than etanercept (a soluble receptor fusion protein) at reducing recurrence of acute anterior uveitis in spondyloarthritis.', 1),
('df000000-0000-0000-0000-000000000034', 'Etanercept has been associated with a higher rate of uveitis flares, and even new-onset uveitis, despite adequate control of axial symptoms.', 2),
('df000000-0000-0000-0000-000000000034', 'Biologic selection in axial spondyloarthritis should account for significant extra-articular manifestations (uveitis, IBD) alongside axial/peripheral joint disease activity.', 3),
('df000000-0000-0000-0000-000000000035', 'NSAIDs are relatively contraindicated in inflammatory bowel disease, as they can precipitate or worsen disease flares, and should be used cautiously or avoided in enteropathic arthritis.', 1),
('df000000-0000-0000-0000-000000000035', 'Proton pump inhibitors mitigate NSAID-related upper GI injury but do not protect against NSAID-associated IBD exacerbation.', 2),
('df000000-0000-0000-0000-000000000035', 'Anti-TNF therapy is a useful option in enteropathic arthritis as it can treat both the joint and bowel components of disease.', 3),
('df000000-0000-0000-0000-000000000036', 'In an ankylosed (fused) spine from long-standing ankylosing spondylitis, even minor trauma can cause an unstable fracture, and plain radiographs frequently miss these fractures due to altered anatomy.', 1),
('df000000-0000-0000-0000-000000000036', 'Fractures through an ankylosed spine carry a high risk of spinal cord injury, including delayed neurological deterioration, even when initial neurological examination is normal.', 2),
('df000000-0000-0000-0000-000000000036', 'A normal plain radiograph in this high-risk context should not be reassuring; urgent CT or MRI and spinal immobilisation are required.', 3),
('df000000-0000-0000-0000-000000000037', 'Psoriatic arthritis can present with an axial phenotype resembling ankylosing spondylitis, particularly in HLA-B27-associated cases.', 1),
('df000000-0000-0000-0000-000000000037', 'As with ankylosing spondylitis, axial disease in psoriatic arthritis unresponsive to NSAIDs is managed with biologic therapy, since conventional synthetic DMARDs lack efficacy for the axial component.', 2),
('df000000-0000-0000-0000-000000000037', 'Oral corticosteroids are relatively avoided in psoriasis due to the risk of triggering a severe flare, including pustular psoriasis, on tapering or withdrawal.', 3),
('df000000-0000-0000-0000-000000000038', 'IL-17 inhibitors are associated with new-onset or exacerbation of inflammatory bowel disease, considered a class effect rather than specific to one agent.', 1),
('df000000-0000-0000-0000-000000000038', 'When IBD develops on an IL-17 inhibitor in a patient with spondyloarthritis, switching to an anti-TNF agent addresses both the axial/joint disease and the bowel disease with a single agent.', 2),
('df000000-0000-0000-0000-000000000038', 'New IBD should be managed with appropriate medical therapy first-line; surgery is reserved for complications or medically refractory disease.', 3),
('df000000-0000-0000-0000-000000000039', 'HLA-B27-associated spondyloarthropathies carry a recognised risk of cardiac involvement, including aortic root disease/aortic regurgitation and conduction abnormalities ranging from first-degree AV block to complete heart block.', 1),
('df000000-0000-0000-0000-000000000039', 'New conduction abnormalities with symptoms in this population warrant cardiology assessment with ambulatory ECG monitoring and echocardiography, as first-degree block can progress to higher-grade block.', 2),
('df000000-0000-0000-0000-000000000039', 'Extra-articular cardiac manifestations should be actively considered and investigated in spondyloarthropathy, not dismissed as unrelated or anxiety-related.', 3),
('df000000-0000-0000-0000-000000000040', 'Secondary loss of response to an anti-TNF agent, characterised by undetectable trough drug levels and high-titre anti-drug antibodies, reflects immunogenicity-driven neutralisation and accelerated clearance of the drug.', 1),
('df000000-0000-0000-0000-000000000040', 'In this scenario, increasing the dose or frequency of the same agent is unlikely to restore efficacy; switching to a different biologic (same or different class) is the appropriate strategy.', 2),
('df000000-0000-0000-0000-000000000040', 'Therapeutic drug monitoring (trough levels and anti-drug antibodies) helps distinguish immunogenicity-driven secondary loss of response from primary non-response or an unrelated disease flare, guiding rational treatment switching.', 3),
('df000000-0000-0000-0000-000000000041', 'Giant cell arteritis with visual symptoms (amaurosis fugax, diplopia, or visual loss) is an ophthalmological emergency requiring immediate high-dose corticosteroid treatment without waiting for biopsy or imaging confirmation.', 1),
('df000000-0000-0000-0000-000000000041', 'Temporal artery biopsy remains diagnostically useful for approximately 2 weeks after starting corticosteroids, so treatment should never be delayed to preserve biopsy yield.', 2),
('df000000-0000-0000-0000-000000000041', 'Untreated or delayed-treatment GCA with visual symptoms carries a high risk of irreversible visual loss from anterior ischaemic optic neuropathy.', 3),
('df000000-0000-0000-0000-000000000042', 'Severe ANCA-associated vasculitis with pulmonary-renal syndrome (diffuse alveolar haemorrhage plus rapidly progressive glomerulonephritis) requires urgent combination induction therapy: high-dose corticosteroids plus rituximab or cyclophosphamide.', 1),
('df000000-0000-0000-0000-000000000042', 'Rituximab and cyclophosphamide have shown broadly equivalent efficacy for induction in ANCA-associated vasculitis in major trials (RAVE, RITUXVAS).', 2),
('df000000-0000-0000-0000-000000000042', 'Plasma exchange is considered as an adjunct in severe renal involvement and/or diffuse alveolar haemorrhage, based on trial evidence (PEXIVAS) and clinical severity.', 3),
('df000000-0000-0000-0000-000000000043', 'Eosinophilic granulomatosis with polyangiitis (EGPA) presents with adult-onset asthma, marked peripheral eosinophilia, sinonasal disease, and vasculitic features such as mononeuritis multiplex, often with MPO-ANCA positivity.', 1),
('df000000-0000-0000-0000-000000000043', 'Mepolizumab (anti-IL-5) is an established steroid-sparing therapy for relapsing/refractory EGPA, targeting the eosinophilic pathway central to disease pathogenesis.', 2),
('df000000-0000-0000-0000-000000000043', 'Ongoing disease activity with corticosteroid toxicity is an indication to add a steroid-sparing biologic rather than persisting with prolonged corticosteroid monotherapy.', 3),
('df000000-0000-0000-0000-000000000044', 'Takayasu arteritis typically affects young women, involving the aorta and its major branches, presenting with constitutional symptoms, claudication, and pulse/blood pressure discrepancies.', 1),
('df000000-0000-0000-0000-000000000044', 'Inflammatory markers (ESR, CRP) correlate poorly with true disease activity in Takayasu arteritis; vascular imaging (MR/CT angiography, PET-CT) alongside clinical assessment is needed to guide treatment decisions.', 2),
('df000000-0000-0000-0000-000000000044', 'Temporal artery biopsy and biopsy of large vessels are not applicable to the diagnosis or monitoring of Takayasu arteritis, distinguishing it from giant cell arteritis in this regard.', 3),
('df000000-0000-0000-0000-000000000045', 'Hepatitis B-associated polyarteritis nodosa is a medium-vessel, ANCA-negative vasculitis driven by ongoing viral replication, presenting with microaneurysms, mononeuritis multiplex, and constitutional symptoms.', 1),
('df000000-0000-0000-0000-000000000045', 'Management prioritises antiviral therapy to control hepatitis B, combined with a short course of corticosteroids (and plasma exchange for severe disease), while avoiding prolonged potent immunosuppression that could worsen viral replication.', 2),
('df000000-0000-0000-0000-000000000045', 'This management approach differs fundamentally from idiopathic (non-HBV-associated) PAN, where longer-term immunosuppression without antiviral considerations is used.', 3),
('df000000-0000-0000-0000-000000000046', $x$Posterior uveitis with retinal vasculitis is a major organ-threatening manifestation of Behcet's disease carrying a significant risk of permanent visual loss, distinct in severity from isolated mucocutaneous ulceration.$x$, 1),
('df000000-0000-0000-0000-000000000046', 'Systemic immunosuppression (azathioprine, escalating to anti-TNF biologics or interferon-alpha for severe/refractory disease) is required for posterior eye involvement, rather than colchicine or topical treatment alone.', 2),
('df000000-0000-0000-0000-000000000046', $x$Treatment intensity in Behcet's disease is tailored to the pattern and severity of organ involvement, ranging from colchicine for mucocutaneous disease to systemic immunosuppression for eye, vascular, or neurological involvement.$x$, 3),
('df000000-0000-0000-0000-000000000047', 'Plasma exchange is considered as an adjunct to standard induction immunosuppression in ANCA-associated vasculitis with severe renal involvement, guided by trial evidence (PEXIVAS) and individualised severity assessment.', 1),
('df000000-0000-0000-0000-000000000047', 'Corticosteroids combined with cyclophosphamide or rituximab remain the core induction regimen in ANCA-associated vasculitis; plasma exchange and steroid-dosing strategies are refinements around this base, not replacements for it.', 2),
('df000000-0000-0000-0000-000000000047', 'Rapidly progressive glomerulonephritis with a high crescent burden on biopsy indicates severe, organ-threatening disease that should prompt consideration of additional therapies to preserve renal function.', 3),
('df000000-0000-0000-0000-000000000048', 'Tocilizumab (IL-6 receptor blockade) is an evidence-based steroid-sparing therapy for relapsing giant cell arteritis, demonstrated in the GiACTA trial to improve sustained remission and reduce cumulative steroid exposure.', 1),
('df000000-0000-0000-0000-000000000048', 'Significant cumulative corticosteroid toxicity (osteoporosis, diabetes, cataracts) in relapsing GCA is an indication to add a steroid-sparing agent rather than persist with higher sustained glucocorticoid doses.', 2),
('df000000-0000-0000-0000-000000000048', 'Temporal artery biopsy is a diagnostic tool at initial presentation, not a tool for monitoring disease activity or guiding treatment escalation in established disease.', 3),
('df000000-0000-0000-0000-000000000049', 'Hepatitis C-associated cryoglobulinaemic vasculitis is driven by ongoing viral infection; direct-acting antiviral therapy is first-line and can resolve the vasculitis in many patients.', 1),
('df000000-0000-0000-0000-000000000049', 'Rituximab is reserved for severe or organ-threatening cryoglobulinaemic vasculitis (e.g. significant renal involvement) as an adjunct to, not a replacement for, antiviral therapy.', 2),
('df000000-0000-0000-0000-000000000049', 'Cyclophosphamide-based regimens are now largely avoided in HCV-associated cryoglobulinaemic vasculitis given the efficacy of modern antiviral therapy combined with targeted B-cell depletion when needed.', 3),
('df000000-0000-0000-0000-000000000050', 'Adults with IgA vasculitis (Henoch-Schonlein purpura) have a significantly worse renal prognosis than children, with higher rates of progression to chronic kidney disease.', 1),
('df000000-0000-0000-0000-000000000050', 'Significant nephritis with crescents on renal biopsy in an adult with IgA vasculitis warrants active immunosuppressive treatment, rather than the more conservative approach often appropriate in mild paediatric disease.', 2),
('df000000-0000-0000-0000-000000000050', 'Renal biopsy provides important prognostic information in adult IgA vasculitis and should guide the decision regarding immunosuppressive therapy.', 3);
